screenPanels.initJs:
function(container, apiUrl, tables) {
  let loginAttempts = 0;
  let isAccountLocked = false;
  let currentLanguage = 'ja';

  const translations = {
    ja: {
      title: 'ハイブリッド申請承認システム',
      subtitle: 'Hybrid Application Approval System',
      userId: 'ユーザーID',
      password: 'パスワード',
      rememberMe: 'ログイン状態を保持する',
      login: 'ログイン',
      forgotPassword: 'パスワードを忘れた方はこちら',
      help: 'ヘルプ・お問い合わせ',
      language: '日本語',
      userIdPlaceholder: 'ユーザーIDを入力してください',
      passwordPlaceholder: 'パスワードを入力してください',
      errorRequired: 'ユーザーIDとパスワードを入力してください',
      errorUserIdRequired: 'ユーザーIDを入力してください',
      errorPasswordRequired: 'パスワードを入力してください',
      errorInvalidCredentials: 'ユーザーIDまたはパスワードが正しくありません',
      errorAccountLocked: 'アカウントがロックされています。管理者にお問い合わせください'
    },
    en: {
      title: 'Hybrid Application Approval System',
      subtitle: 'ハイブリッド申請承認システム',
      userId: 'User ID',
      password: 'Password',
      rememberMe: 'Remember me',
      login: 'Login',
      forgotPassword: 'Forgot your password?',
      help: 'Help & Support',
      language: 'English',
      userIdPlaceholder: 'Enter your user ID',
      passwordPlaceholder: 'Enter your password',
      errorRequired: 'Please enter user ID and password',
      errorUserIdRequired: 'Please enter user ID',
      errorPasswordRequired: 'Please enter password',
      errorInvalidCredentials: 'Invalid user ID or password',
      errorAccountLocked: 'Account is locked. Please contact administrator'
    }
  };

  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.display = 'none';
  }

  function updateLanguage() {
    const t = translations[currentLanguage];

    container.querySelector('h1').textContent = t.title;
    container.querySelector('p').textContent = t.subtitle;
    container.querySelector('label[for="user-id"]').textContent = t.userId;
    container.querySelector('label[for="password"]').textContent = t.password;
    container.querySelector('label[for="remember-me"]').textContent = t.rememberMe;
    container.querySelector('#login-button').textContent = t.login;
    container.querySelector('#forgot-password').textContent = t.forgotPassword;
    container.querySelector('#help-link').textContent = t.help;
    container.querySelector('#current-language').textContent = t.language;
    container.querySelector('#user-id').placeholder = t.userIdPlaceholder;
    container.querySelector('#password').placeholder = t.passwordPlaceholder;
  }

  // パスワード表示切り替え
  container.querySelector('#toggle-password').addEventListener('click', function() {
    const passwordInput = container.querySelector('#password');
    const toggleBtn = container.querySelector('#toggle-password');

    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      toggleBtn.textContent = '🙈';
    } else {
      passwordInput.type = 'password';
      toggleBtn.textContent = '👁';
    }
  });

  // 言語切り替え
  container.querySelector('#language-toggle').addEventListener('click', function() {
    currentLanguage = currentLanguage === 'ja' ? 'en' : 'ja';
    updateLanguage();
  });

  // パスワード忘れリンク
  container.querySelector('#forgot-password').addEventListener('click', function(e) {
    e.preventDefault();
    // パスワードリセット画面への遷移をシミュレート
    alert('パスワードリセット画面に遷移します');
  });

  // ヘルプリンク
  container.querySelector('#help-link').addEventListener('click', function(e) {
    e.preventDefault();
    // ヘルプページへの遷移をシミュレート
    alert('ヘルプページに遷移します');
  });

  // ログインフォーム送信
  container.querySelector('#login-form').addEventListener('submit', async function(e) {
    e.preventDefault();
    hideError();

    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;
    const rememberMe = container.querySelector('#remember-me').checked;
    const t = translations[currentLanguage];

    // バリデーション
    if (!userId && !password) {
      showError(t.errorRequired);
      return;
    }
    if (!userId) {
      showError(t.errorUserIdRequired);
      return;
    }
    if (!password) {
      showError(t.errorPasswordRequired);
      return;
    }

    // アカウントロック確認
    if (isAccountLocked) {
      showError(t.errorAccountLocked);
      return;
    }

    // ユーザー認証（テスト用の簡易実装）
    const users = tables[0]?.records || [];
    const user = users.find(u => u.メールアドレス === userId || u.ユーザー名 === userId);

    if (!user || password !== 'correct_password') {
      loginAttempts++;

      if (loginAttempts >= 5) {
        isAccountLocked = true;
        showError(t.errorAccountLocked);
      } else {
        showError(t.errorInvalidCredentials);
      }
      return;
    }

    // ログイン成功
    loginAttempts = 0;

    // ログイン状態保持
    if (rememberMe) {
      localStorage.setItem('loginState', JSON.stringify({
        userId: userId,
        timestamp: Date.now(),
        rememberMe: true
      }));
    }

    // 最終ログイン日時更新
    if (window.aivicApi) {
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });
    }

    // ダッシュボードへ遷移（メニュー選択画面をシミュレート）
    alert('ログイン成功！ダッシュボードに遷移します。');

    // 実際の画面遷移（新規申請画面へ）
    if (window.showScreen) {
      window.showScreen("scr-1779422326698");
    }
  });

  // 初期化時にログイン状態確認
  const savedLoginState = localStorage.getItem('loginState');
  if (savedLoginState) {
    try {
      const loginData = JSON.parse(savedLoginState);
      if (loginData.rememberMe && Date.now() - loginData.timestamp < 30 * 24 * 60 * 60 * 1000) { // 30日間有効
        container.querySelector('#user-id').value = loginData.userId;
        container.querySelector('#remember-me').checked = true;
      }
    } catch (e) {
      localStorage.removeItem('loginState');
    }
  }

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input[type="text"], input[type="password"]');
  inputs.forEach(input => {
    input.addEventListener('focus', function() {
      this.style.outline = 'none';
      this.style.borderColor = 'var(--primary)';
      this.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', function() {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
      this.style.boxShadow = 'none';
    });
  });

  // ログインボタンのホバー効果
  const loginButton = container.querySelector('#login-button');
  loginButton.addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });

  loginButton.addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  // 初期言語設定
  updateLanguage();
}

function(container, apiUrl, tables) {
  let uploadedFiles = [];
  let currentDetection = null;

  // DOM要素の取得
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const fileSelectBtn = container.querySelector('#file-select-btn');
  const uploadProgress = container.querySelector('#upload-progress');
  const uploadContent = container.querySelector('#upload-content');
  const progressBar = container.querySelector('#progress-bar');
  const uploadedFilesDiv = container.querySelector('#uploaded-files');
  const noFilesDiv = container.querySelector('#no-files');
  const detectedType = container.querySelector('#detected-type');
  const confidenceBar = container.querySelector('#confidence-bar');
  const confidenceText = container.querySelector('#confidence-text');
  const confidenceWarning = container.querySelector('#confidence-warning');
  const manualDocType = container.querySelector('#manual-doc-type');
  const approvalFlowName = container.querySelector('#approval-flow-name');
  const approversList = container.querySelector('#approvers-list');
  const errorMessage = container.querySelector('#error-message');

  // 文書種別マスタの初期化
  const docTypes = tables[2]?.records || [];

  // 承認フロー定義の初期化
  const approvalFlows = tables[3]?.records || [];

  // ユーザーマスタの初期化
  const users = tables[0]?.records || [];

  // ファイルアップロード処理
  function handleFileUpload(files) {
    if (!files || files.length === 0) return;

    // ファイル形式チェック
    const allowedTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
    const maxSize = 10 * 1024 * 1024; // 10MB

    for (let file of files) {
      if (!allowedTypes.includes(file.type)) {
        showError(`対応していないファイル形式です: ${file.name}`);
        return;
      }
      if (file.size > maxSize) {
        showError(`ファイルサイズが上限を超過しています: ${file.name}`);
        return;
      }
    }

    // アップロード処理のシミュレーション
    uploadContent.style.display = 'none';
    uploadProgress.style.display = 'block';

    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      progressBar.style.width = progress + '%';

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          uploadContent.style.display = 'block';
          uploadProgress.style.display = 'none';
          progressBar.style.width = '0%';

          // ファイルを追加
          Array.from(files).forEach(file => {
            uploadedFiles.push({
              id: Date.now() + Math.random(),
              name: file.name,
              size: file.size,
              type: file.type,
              file: file
            });
          });

          renderUploadedFiles();
          performAutoDetection();
        }, 500);
      }
    }, 100);
  }

  // アップロード済みファイル表示
  function renderUploadedFiles() {
    if (uploadedFiles.length === 0) {
      noFilesDiv.style.display = 'block';
      return;
    }

    noFilesDiv.style.display = 'none';
    const filesHtml = uploadedFiles.map(file => `
      <div style="display: flex; justify-content: between; align-items: center; padding: 6px; background: rgba(255,255,255,0.05); border-radius: 4px; margin-bottom: 4px;">
        <div style="flex: 1;">
          <div style="font-size: 12px; color: var(--text);">${file.name}</div>
          <div style="font-size: 10px; color: var(--text-muted);">${(file.size / 1024).toFixed(1)} KB</div>
        </div>
        <button class="file-remove-btn" data-id="${file.id}" style="background: transparent; border: none; color: var(--text-muted); cursor: pointer; padding: 2px 6px; font-size: 12px;">×</button>
      </div>
    `).join('');

    uploadedFilesDiv.innerHTML = filesHtml;
  }

  // 自動判別処理
  function performAutoDetection() {
    if (uploadedFiles.length === 0) return;

    // 判別処理のシミュレーション
    setTimeout(() => {
      const detectionResults = [
        { type: 'vacation', name: '休暇申請書', confidence: 0.95 },
        { type: 'expense', name: '経費申請書', confidence: 0.88 },
        { type: 'approval', name: '稟議書', confidence: 0.72 },
        { type: 'purchase', name: '購買申請書', confidence: 0.45 }
      ];

      const result = detectionResults[Math.floor(Math.random() * detectionResults.length)];
      currentDetection = result;

      detectedType.textContent = result.name;
      confidenceBar.style.width = (result.confidence * 100) + '%';
      confidenceText.textContent = Math.round(result.confidence * 100) + '%';

      // 信頼度が低い場合の警告
      if (result.confidence < 0.7) {
        confidenceWarning.style.display = 'block';
      } else {
        confidenceWarning.style.display = 'none';
      }

      // 手動選択を自動判別結果に設定
      manualDocType.value = result.type;

      updateApprovalFlow();
    }, 1000);
  }

  // 承認フロー更新
  function updateApprovalFlow() {
    const selectedType = manualDocType.value;
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || 'normal';

    if (!selectedType) {
      approvalFlowName.textContent = '承認フローが設定されていません';
      approversList.textContent = '文書種別を選択すると承認者が表示されます';
      return;
    }

    // 文書種別に対応する承認フローを検索
    const docType = docTypes.find(dt => dt.文書種別コード === selectedType);
    if (!docType) return;

    const flows = approvalFlows.filter(af => af.文書種別ID === docType.文書種別ID);

    if (flows.length === 0) {
      approvalFlowName.textContent = '承認フローが設定されていません';
      approversList.textContent = '該当する承認フローがありません';
      return;
    }

    // 緊急度に応じた承認フロー名
    let flowName = docType.文書種別名 + '承認フロー';
    if (urgency === 'urgent') {
      flowName += '（緊急）';
    } else if (urgency === 'high') {
      flowName += '（高優先度）';
    }

    approvalFlowName.textContent = flowName;

    // 承認者一覧の表示
    const sortedFlows = flows.sort((a, b) => a.承認ステップ番号 - b.承認ステップ番号);
    const approvers = sortedFlows.map(flow => {
      const user = users.find(u => u.ユーザーID === flow.承認者ユーザーID);
      return user ? `${flow.承認ステップ番号}. ${user.ユーザー名} (${user.役職 || '担当者'})` : `${flow.承認ステップ番号}. 未設定`;
    });

    if (urgency === 'urgent' && approvers.length > 1) {
      // 緊急時は承認ステップを短縮
      approversList.innerHTML = `
        <div style="margin-bottom: 4px;">緊急申請のため承認ステップを短縮:</div>
        <div>${approvers.slice(0, Math.ceil(approvers.length / 2)).join('<br>')}</div>
      `;
    } else {
      approversList.innerHTML = approvers.join('<br>');
    }
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // イベントリスナー
  fileSelectBtn.addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    handleFileUpload(e.target.files);
  });

  // ドラッグ&ドロップ
  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
  });

  uploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    handleFileUpload(e.dataTransfer.files);
  });

  // ファイル削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.file-remove-btn');
    if (removeBtn) {
      const fileId = parseFloat(removeBtn.dataset.id);
      uploadedFiles = uploadedFiles.filter(f => f.id !== fileId);
      renderUploadedFiles();

      if (uploadedFiles.length === 0) {
        detectedType.textContent = '未判別';
        confidenceBar.style.width = '0%';
        confidenceText.textContent = '0%';
        confidenceWarning.style.display = 'none';
        currentDetection = null;
        manualDocType.value = '';
        updateApprovalFlow();
      }
    }
  });

  // 文書種別変更時の承認フロー更新
  manualDocType.addEventListener('change', updateApprovalFlow);

  // 緊急度変更時の承認フロー更新
  container.addEventListener('change', (e) => {
    if (e.target.name === 'urgency') {
      updateApprovalFlow();
    }
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    uploadedFiles = [];
    currentDetection = null;
    renderUploadedFiles();
    detectedType.textContent = '未判別';
    confidenceBar.style.width = '0%';
    confidenceText.textContent = '0%';
    confidenceWarning.style.display = 'none';
    manualDocType.value = '';
    container.querySelector('#application-title').value = '';
    container.querySelector('#application-description').value = '';
    container.querySelector('input[name="urgency"][value="normal"]').checked = true;
    updateApprovalFlow();
    errorMessage.style.display = 'none';
  });

  // 申請登録ボタン
  container.querySelector('#btn-register').addEventListener('click', async () => {
    const title = container.querySelector('#application-title').value.trim();
    const description = container.querySelector('#application-description').value.trim();
    const docType = manualDocType.value;
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value;

    // バリデーション
    if (!title) {
      showError('申請タイトルを入力してください');
      return;
    }

    if (uploadedFiles.length === 0) {
      showError('申請書類をアップロードしてください');
      return;
    }

    if (!docType) {
      showError('文書種別を選択してください');
      return;
    }

    // 承認者チェック
    const docTypeRecord = docTypes.find(dt => dt.文書種別コード === docType);
    const flows = approvalFlows.filter(af => af.文書種別ID === docTypeRecord?.文書種別ID);

    if (flows.length === 0) {
      showError('承認者が設定されていません。管理者にお問い合わせください。');
      return;
    }

    try {
      // 申請書類の保存
      const applicationData = {
        申請種別: docType,
        申請タイトル: title,
        申請内容: description,
        承認状態: '申請中',
        承認段階: 1,
        緊急フラグ: urgency === 'urgent',
        添付ファイル有無: true,
        現在承認者ID: flows.find(f => f.承認ステップ番号 === 1)?.承認者ユーザーID
      };

      const saved = await window.aivicApi.save(1, applicationData);

      if (saved) {
        alert('申請書類が正常に登録されました。');
        container.querySelector('#btn-clear').click(); // フォームクリア
      }
    } catch (error) {
      showError('申請登録に失敗しました。もう一度お試しください。');
    }
  });

  // 初期化
  renderUploadedFiles();
  updateApprovalFlow();
}

function(container, apiUrl, tables) {
  let allApplications = [];
  let allUsers = [];
  let allSteps = [];
  let allRoutes = [];
  let sortOrder = { column: null, direction: 'asc' };

  // ユーザー情報とステップ情報を取得
  async function loadRelatedData() {
    try {
      allUsers = await window.aivicApi.list(0) || []; // ユーザー
      allSteps = await window.aivicApi.list(4) || []; // 承認ステップ
      allRoutes = await window.aivicApi.list(7) || []; // 処理ルート
    } catch (error) {
      console.error('関連データの取得に失敗:', error);
    }
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = allUsers.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : '';
  }

  // 現在の承認者を取得
  function getCurrentApprover(applicationId) {
    const route = allRoutes.find(r => r.申請書類ID === applicationId);
    if (route && route.現在承認者ID) {
      return getUserName(route.現在承認者ID);
    }
    return '';
  }

  // 進捗率を計算
  function calculateProgress(applicationId) {
    const steps = allSteps.filter(s => s.申請書類ID === applicationId);
    if (steps.length === 0) return 0;

    const completedSteps = steps.filter(s => s.承認状態 === '承認済').length;
    return Math.round((completedSteps / steps.length) * 100);
  }

  // 遅延日数を計算
  function calculateDelayDays(createdAt, status) {
    if (status === '承認済' || status === '却下' || status === '取下げ') return 0;

    const created = new Date(createdAt);
    const now = new Date();
    const diffTime = now - created;
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    // 3日以上経過していれば遅延とみなす
    return diffDays > 3 ? diffDays - 3 : 0;
  }

  // 優先度の表示
  function getPriorityDisplay(priority) {
    const priorities = {
      1: { text: '低', color: '#6b7280' },
      2: { text: '通常', color: '#3b82f6' },
      3: { text: '高', color: '#f59e0b' },
      4: { text: '緊急', color: '#ef4444' }
    };
    const p = priorities[priority] || priorities[2];
    return `<span style="color: ${p.color}; font-weight: 500;">${p.text}</span>`;
  }

  // 承認状況の表示
  function getStatusDisplay(status) {
    const statusColors = {
      '申請中': '#3b82f6',
      '承認待ち': '#f59e0b', 
      '承認済': '#10b981',
      '却下': '#ef4444',
      '取下げ': '#6b7280'
    };
    const color = statusColors[status] || '#6b7280';
    return `<span style="color: ${color}; font-weight: 500;">${status}</span>`;
  }

  // 進捗バーの表示
  function getProgressBar(progress) {
    return `
      <div style="width: 80px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; position: relative;">
        <div style="width: ${progress}%; height: 100%; background: var(--primary); border-radius: 3px;"></div>
      </div>
      <span style="font-size: 11px; color: var(--text-muted); margin-left: 4px;">${progress}%</span>
    `;
  }

  // テーブル行を再描画
  function renderRows(applications) {
    const tbody = container.querySelector('#applications-tbody');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!applications || applications.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.style.display = 'block';
      return;
    }

    noDataMessage.style.display = 'none';

    tbody.innerHTML = applications.map(app => {
      const applicantName = getUserName(app.申請者ID);
      const currentApprover = getCurrentApprover(app.申請書類ID);
      const progress = calculateProgress(app.申請書類ID);
      const delayDays = calculateDelayDays(app.作成日時, app.承認状態);
      const isDelayed = delayDays > 0;

      // 処理ルートから優先度を取得
      const route = allRoutes.find(r => r.申請書類ID === app.申請書類ID);
      const priority = route ? route.優先度 : 2;

      return `
        <tr data-id="${app.申請書類ID}" style="${isDelayed ? 'background: rgba(239, 68, 68, 0.1);' : ''}" class="application-row">
          <td style="padding: 6px 10px; font-size: 13px;">
            <a href="#" class="detail-link" data-id="${app.申請書類ID}" style="color: var(--primary); text-decoration: none;">${app.申請書類ID.substring(0, 8)}</a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${app.申請種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${app.申請タイトル || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${new Date(app.作成日時).toLocaleDateString('ja-JP')}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${getStatusDisplay(app.承認状態)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${currentApprover}</td>
          <td style="padding: 6px 10px; font-size: 13px; display: flex; align-items: center;">${getProgressBar(progress)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${getPriorityDisplay(priority)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            ${delayDays > 0 ? `<span style="color: #ef4444; font-weight: 500;">${delayDays}日</span>` : '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${app.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">案件詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 検索・フィルター処理
  function filterApplications() {
    const documentType = container.querySelector('#filter-document-type').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const applicantName = container.querySelector('#filter-applicant').value.trim();
    const approverName = container.querySelector('#filter-approver').value.trim();

    let filtered = allApplications.filter(app => {
      // 文書種別フィルター
      if (documentType && app.申請種別 !== documentType) return false;

      // 承認状況フィルター
      if (approvalStatus && app.承認状態 !== approvalStatus) return false;

      // 申請日フィルター
      const appDate = new Date(app.作成日時).toISOString().split('T')[0];
      if (startDate && appDate < startDate) return false;
      if (endDate && appDate > endDate) return false;

      // 申請者名フィルター
      if (applicantName) {
        const userName = getUserName(app.申請者ID);
        if (!userName.includes(applicantName)) return false;
      }

      // 承認者名フィルター
      if (approverName) {
        const currentApprover = getCurrentApprover(app.申請書類ID);
        if (!currentApprover.includes(approverName)) return false;
      }

      return true;
    });

    renderRows(filtered);
  }

  // ソート処理
  function sortApplications(column) {
    if (sortOrder.column === column) {
      sortOrder.direction = sortOrder.direction === 'asc' ? 'desc' : 'asc';
    } else {
      sortOrder.column = column;
      sortOrder.direction = 'asc';
    }

    const sorted = [...allApplications].sort((a, b) => {
      let aVal, bVal;

      if (column === '優先度') {
        const routeA = allRoutes.find(r => r.申請書類ID === a.申請書類ID);
        const routeB = allRoutes.find(r => r.申請書類ID === b.申請書類ID);
        aVal = routeA ? routeA.優先度 : 2;
        bVal = routeB ? routeB.優先度 : 2;
      } else {
        aVal = a[column] || '';
        bVal = b[column] || '';
      }

      if (sortOrder.direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    allApplications = sorted;
    filterApplications();
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }
    return true;
  }

  // 特殊文字チェック
  function containsSpecialChars(str) {
    const specialChars = /[<>'"&]/;
    return specialChars.test(str);
  }

  // CSVエクスポート
  function exportToCSV() {
    const headers = ['申請ID', '申請者', '申請種別', '申請タイトル', '申請日', '承認状況', '現在承認者', '進捗率', '優先度', '遅延日数'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...allApplications.map(app => {
        const applicantName = getUserName(app.申請者ID);
        const currentApprover = getCurrentApprover(app.申請書類ID);
        const progress = calculateProgress(app.申請書類ID);
        const delayDays = calculateDelayDays(app.作成日時, app.承認状態);
        const route = allRoutes.find(r => r.申請書類ID === app.申請書類ID);
        const priority = route ? route.優先度 : 2;
        const priorityText = ['', '低', '通常', '高', '緊急'][priority] || '通常';

        return [
          app.申請書類ID,
          applicantName,
          app.申請種別 || '',
          `"${(app.申請タイトル || '').replace(/"/g, '""')}"`,
          new Date(app.作成日時).toLocaleDateString('ja-JP'),
          app.承認状態,
          currentApprover,
          `${progress}%`,
          priorityText,
          delayDays > 0 ? `${delayDays}日` : '-'
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `承認フロー進捗_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      await loadRelatedData();
      allApplications = await window.aivicApi.list(1) || []; // 申請書類
      renderRows(allApplications);
    } catch (error) {
      console.error('データの読み込みに失敗:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', () => {
    if (!validateDateRange()) return;

    const applicantName = container.querySelector('#filter-applicant').value.trim();
    const approverName = container.querySelector('#filter-approver').value.trim();

    if (containsSpecialChars(applicantName)) {
      showError('申請者名に使用できない文字が含まれています');
      return;
    }

    if (containsSpecialChars(approverName)) {
      showError('承認者名に使用できない文字が含まれています');
      return;
    }

    filterApplications();
  });

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#filter-document-type').value = '';
    container.querySelector('#filter-approval-status').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-applicant').value = '';
    container.querySelector('#filter-approver').value = '';
    renderRows(allApplications);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportToCSV);

  container.querySelector('#btn-delay-check').addEventListener('click', () => {
    window.showScreen("scr-1779422271790");
  });

  container.querySelector('#btn-route-change').addEventListener('click', () => {
    window.showScreen("scr-1779422283293");
  });

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('[data-sort]');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      sortApplications(column);
    }

    const detailBtn = e.target.closest('.detail-btn');
    const detailLink = e.target.closest('.detail-link');
    if (detailBtn || detailLink) {
      e.preventDefault();
      window.showScreen("scr-1779422369173");
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  let allDelayCases = [];
  let filteredCases = [];
  let selectedCases = new Set();

  // 遅延レベル判定関数
  function getDelayLevel(delayDays) {
    if (delayDays >= 7) return { level: '緊急', color: '#ff4444' };
    if (delayDays >= 3) return { level: '注意', color: '#ff8800' };
    return { level: '軽微', color: '#ffaa00' };
  }

  // 遅延日数計算関数
  function calculateDelayDays(updateTime) {
    const now = new Date();
    const updated = new Date(updateTime);
    const diffTime = now - updated;
    return Math.floor(diffTime / (1000 * 60 * 60 * 24));
  }

  // 遅延案件データ生成関数
  function generateDelayCases() {
    const applications = tables[1]?.records || [];
    const users = tables[0]?.records || [];
    const steps = tables[4]?.records || [];

    return applications
      .filter(app => {
        const delayDays = calculateDelayDays(app.更新日時 || app.作成日時);
        return delayDays > 0 && (app.承認状態 === '申請中' || app.承認状態 === '承認中');
      })
      .map(app => {
        const applicant = users.find(u => u.ユーザーID === app.申請者ID);
        const currentApprover = users.find(u => u.ユーザーID === app.現在承認者ID);
        const delayDays = calculateDelayDays(app.更新日時 || app.作成日時);
        const delayInfo = getDelayLevel(delayDays);

        return {
          id: app.申請書類ID,
          申請ID: app.申請書類ID?.substring(0, 8) || 'N/A',
          申請種別: app.申請種別 || 'N/A',
          申請者: applicant?.ユーザー名 || 'N/A',
          現在承認者: currentApprover?.ユーザー名 || 'N/A',
          遅延日数: delayDays,
          遅延レベル: delayInfo.level,
          遅延レベル色: delayInfo.color,
          最終更新: new Date(app.更新日時 || app.作成日時).toLocaleDateString('ja-JP'),
          承認状態: app.承認状態 || 'N/A'
        };
      })
      .sort((a, b) => b.遅延日数 - a.遅延日数);
  }

  // テーブル再描画関数
  function renderDelayCases(cases) {
    const tbody = container.querySelector('#delay-cases-tbody');
    const countEl = container.querySelector('#delay-count');

    countEl.textContent = `${cases.length}件`;

    if (cases.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">遅延案件はありません</td></tr>';
      return;
    }

    tbody.innerHTML = cases.map(c => `
      <tr data-id="${c.id}" style="height: 36px;">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <input type="checkbox" class="case-checkbox" data-id="${c.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${c.申請ID}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${c.申請種別}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${c.申請者}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${c.現在承認者}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 600;">${c.遅延日数}日</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 500; background: ${c.遅延レベル色}20; color: ${c.遅延レベル色}; border: 1px solid ${c.遅延レベル色}40;">${c.遅延レベル}</span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${c.最終更新}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn reminder-btn" data-id="${c.id}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">催促送信</button>
        </td>
      </tr>
    `).join('');

    updateBulkReminderButton();
  }

  // フィルター適用関数
  function applyFilters() {
    const docType = container.querySelector('#filter-document-type').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;
    const delayLevel = container.querySelector('#filter-delay-level').value;

    filteredCases = allDelayCases.filter(c => {
      if (docType && c.申請種別 !== docType) return false;
      if (approvalStatus && c.承認状態 !== approvalStatus) return false;
      if (delayLevel && c.遅延レベル !== delayLevel) return false;
      return true;
    });

    renderDelayCases(filteredCases);
  }

  // 一括催促ボタン状態更新
  function updateBulkReminderButton() {
    const bulkBtn = container.querySelector('#btn-bulk-reminder');
    bulkBtn.disabled = selectedCases.size === 0;
  }

  // チェックボックス状態更新
  function updateCheckboxes() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const caseCheckboxes = container.querySelectorAll('.case-checkbox');

    if (caseCheckboxes.length === 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
      return;
    }

    const checkedCount = Array.from(caseCheckboxes).filter(cb => cb.checked).length;

    if (checkedCount === 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    } else if (checkedCount === caseCheckboxes.length) {
      selectAllCheckbox.checked = true;
      selectAllCheckbox.indeterminate = false;
    } else {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = true;
    }
  }

  // 催促通知送信関数
  async function sendReminder(caseIds) {
    try {
      // 通知履歴に記録
      for (const caseId of caseIds) {
        const caseData = allDelayCases.find(c => c.id === caseId);
        if (caseData) {
          await window.aivicApi.save(5, {
            申請書類ID: caseId,
            通知対象ユーザーID: caseData.現在承認者,
            通知種別: '催促通知',
            通知タイトル: `【催促】${caseData.申請種別}の承認をお願いします`,
            通知内容: `申請者: ${caseData.申請者}\n遅延日数: ${caseData.遅延日数}日\n至急承認をお願いいたします。`,
            送信方法: 'メール',
            送信状態: '送信完了',
            送信日時: new Date().toISOString(),
            既読フラグ: false,
            再送回数: 0,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user'
          });
        }
      }

      alert(`${caseIds.length}件の催促通知を送信しました。`);

      // 選択状態をクリア
      selectedCases.clear();
      container.querySelectorAll('.case-checkbox').forEach(cb => cb.checked = false);
      container.querySelector('#select-all').checked = false;
      updateBulkReminderButton();

    } catch (error) {
      alert('催促通知の送信に失敗しました。ネットワーク接続を確認してください。');
    }
  }

  // 初期データ読み込み
  allDelayCases = generateDelayCases();
  filteredCases = [...allDelayCases];
  renderDelayCases(filteredCases);

  // フィルターボタンイベント
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  // 全選択チェックボックスイベント
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checked = e.target.checked;
    container.querySelectorAll('.case-checkbox').forEach(cb => {
      cb.checked = checked;
      if (checked) {
        selectedCases.add(cb.dataset.id);
      } else {
        selectedCases.delete(cb.dataset.id);
      }
    });
    updateBulkReminderButton();
  });

  // 個別チェックボックスイベント
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('case-checkbox')) {
      const caseId = e.target.dataset.id;
      if (e.target.checked) {
        selectedCases.add(caseId);
      } else {
        selectedCases.delete(caseId);
      }
      updateCheckboxes();
      updateBulkReminderButton();
    }
  });

  // 一括催促送信ボタンイベント
  container.querySelector('#btn-bulk-reminder').addEventListener('click', () => {
    if (selectedCases.size === 0) {
      alert('催促通知を送信する案件を選択してください。');
      return;
    }

    const modal = container.querySelector('#reminder-confirm-modal');
    const message = container.querySelector('#reminder-confirm-message');
    message.textContent = `選択した${selectedCases.size}件の案件に催促通知を送信しますか？`;
    modal.style.display = 'block';
  });

  // 個別催促送信ボタンイベント
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('reminder-btn')) {
      const caseId = e.target.dataset.id;
      const caseData = allDelayCases.find(c => c.id === caseId);

      const modal = container.querySelector('#reminder-confirm-modal');
      const message = container.querySelector('#reminder-confirm-message');
      message.textContent = `${caseData.申請種別}（申請者: ${caseData.申請者}）に催促通知を送信しますか？`;
      modal.style.display = 'block';

      // 一時的に選択状態にする
      selectedCases.clear();
      selectedCases.add(caseId);
    }
  });

  // 催促通知確認モーダルイベント
  container.querySelector('#btn-confirm-reminder').addEventListener('click', async () => {
    const modal = container.querySelector('#reminder-confirm-modal');
    modal.style.display = 'none';

    await sendReminder(Array.from(selectedCases));
    window.showScreen("scr-1779422392638");
  });

  container.querySelector('#btn-cancel-reminder').addEventListener('click', () => {
    container.querySelector('#reminder-confirm-modal').style.display = 'none';
  });

  // 遅延検知設定ボタンイベント
  container.querySelector('#btn-delay-settings').addEventListener('click', () => {
    container.querySelector('#delay-settings-modal').style.display = 'block';
  });

  // 設定保存ボタンイベント
  container.querySelector('#btn-save-settings').addEventListener('click', async () => {
    const deadlineDays = parseInt(container.querySelector('#setting-deadline-days').value);
    const warningDays = parseInt(container.querySelector('#setting-warning-days').value);
    const escalationDays = parseInt(container.querySelector('#setting-escalation-days').value);
    const businessDays = container.querySelector('#setting-business-days').checked;

    if (deadlineDays < 1 || warningDays < 1 || escalationDays < 1) {
      alert('日数は1以上の値を入力してください。');
      return;
    }

    try {
      await window.aivicApi.save(7, {
        文書種別ID: null,
        承認ステップID: null,
        設定名: 'デフォルト遅延検知設定',
        期限日数: deadlineDays,
        警告日数: warningDays,
        エスカレーション日数: escalationDays,
        営業日計算フラグ: businessDays,
        有効フラグ: true,
        備考: 'システム管理者による設定',
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'current-user',
        更新者ID: 'current-user'
      });

      alert('遅延検知設定を保存しました。');
      container.querySelector('#delay-settings-modal').style.display = 'none';

      // データを再生成して表示更新
      allDelayCases = generateDelayCases();
      applyFilters();

    } catch (error) {
      alert('設定の保存に失敗しました。');
    }
  });

  container.querySelector('#btn-cancel-settings').addEventListener('click', () => {
    container.querySelector('#delay-settings-modal').style.display = 'none';
  });

  // 通知履歴ボタンイベント
  container.querySelector('#btn-notification-history').addEventListener('click', () => {
    // 通知履歴画面への遷移（仮想的な画面ID）
    alert('通知履歴画面への遷移機能は実装予定です。');
  });

  // モーダル外クリックで閉じる
  container.addEventListener('click', (e) => {
    if (e.target.id === 'delay-settings-modal') {
      container.querySelector('#delay-settings-modal').style.display = 'none';
    }
    if (e.target.id === 'reminder-confirm-modal') {
      container.querySelector('#reminder-confirm-modal').style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  let currentApplicationData = null;
  let currentApprovalSteps = [];

  // テーブルインデックス定義
  const APPLICATION_TABLE = 1; // 申請書類
  const APPROVAL_STEP_TABLE = 4; // 承認ステップ
  const APPROVAL_FLOW_TABLE = 3; // 承認フロー定義
  const USER_TABLE = 0; // ユーザー
  const ROUTE_TABLE = 9; // 処理ルート
  const NOTIFICATION_TABLE = 5; // 通知履歴

  // DOM要素取得
  const applicationSelect = container.querySelector('#application-select');
  const newRouteSelect = container.querySelector('#new-route-select');
  const currentRouteDisplay = container.querySelector('#current-route-display');
  const approvalStepsTbody = container.querySelector('#approval-steps-tbody');
  const changeReasonTextarea = container.querySelector('#change-reason');
  const reasonCharCount = container.querySelector('#reason-char-count');
  const notificationMessage = container.querySelector('#notification-message');
  const messageCharCount = container.querySelector('#message-char-count');
  const confirmationModal = container.querySelector('#confirmation-modal');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');

  // 承認ステップ再描画関数
  function renderApprovalSteps(steps) {
    if (!steps || steps.length === 0) {
      approvalStepsTbody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: var(--text-muted); padding: 20px;">承認ステップがありません</td></tr>';
      return;
    }

    approvalStepsTbody.innerHTML = steps.map(step => {
      const user = tables[USER_TABLE].records.find(u => u.id === step.承認者ID) || {};
      const statusBadge = getStatusBadge(step.承認状態);

      return `
        <tr data-id="${step.id}">
          <td>${step.ステップ番号}</td>
          <td>${user.ユーザー名 || '未設定'}</td>
          <td>${statusBadge}</td>
          <td>
            <button class="action-btn secondary change-approver-btn" data-testid="change-approver-button" data-step-id="${step.id}">承認者変更</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const statusMap = {
      '未承認': { bg: 'rgba(156, 163, 175, 0.2)', color: 'var(--text)' },
      '承認済': { bg: 'rgba(34, 197, 94, 0.2)', color: '#22c55e' },
      '否認': { bg: 'rgba(239, 68, 68, 0.2)', color: '#ef4444' },
      '保留': { bg: 'rgba(251, 191, 36, 0.2)', color: '#fbbf24' }
    };

    const style = statusMap[status] || statusMap['未承認'];
    return `<span style="background: ${style.bg}; color: ${style.color}; padding: 2px 8px; border-radius: 4px; font-size: 11px;">${status}</span>`;
  }

  // エラー表示
  function showError(message) {
    errorText.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 申請書類選択時の処理
  applicationSelect.addEventListener('change', async function() {
    const applicationId = this.value;
    if (!applicationId) {
      currentApplicationData = null;
      currentApprovalSteps = [];
      currentRouteDisplay.textContent = '申請書類を選択すると現在の処理ルートが表示されます';
      renderApprovalSteps([]);
      return;
    }

    try {
      // 申請書類データ取得
      const applications = await window.aivicApi.list(APPLICATION_TABLE);
      currentApplicationData = applications.find(app => app.id === applicationId);

      if (currentApplicationData) {
        // 現在の処理ルート表示
        const routeText = `申請種別: ${currentApplicationData.申請種別} | 承認状態: ${currentApplicationData.承認状態} | 現在承認者: ${currentApplicationData.現在承認者ID || '未設定'}`;
        currentRouteDisplay.textContent = routeText;

        // 承認ステップ取得・表示
        const approvalSteps = await window.aivicApi.list(APPROVAL_STEP_TABLE);
        currentApprovalSteps = approvalSteps.filter(step => step.申請書類ID === applicationId);
        renderApprovalSteps(currentApprovalSteps);
      }
    } catch (error) {
      showError('申請書類の詳細取得に失敗しました');
    }
  });

  // 新しい処理ルート選択時の警告
  newRouteSelect.addEventListener('change', function() {
    const selectedRoute = this.value;
    if (selectedRoute && currentApplicationData) {
      // 同一ルート選択チェック（簡易実装）
      if (selectedRoute === '1' && currentApplicationData.承認状態 === '申請中') {
        if (confirm('現在と同じ処理ルートが選択されています。変更する必要がありますか？')) {
          // 継続
        } else {
          this.value = '';
        }
      }
    }
  });

  // 文字数カウント
  changeReasonTextarea.addEventListener('input', function() {
    const count = this.value.length;
    reasonCharCount.textContent = count;
    if (count > 500) {
      this.value = this.value.substring(0, 500);
      reasonCharCount.textContent = '500';
    }
  });

  notificationMessage.addEventListener('input', function() {
    const count = this.value.length;
    messageCharCount.textContent = count;
    if (count > 1000) {
      this.value = this.value.substring(0, 1000);
      messageCharCount.textContent = '1000';
    }
  });

  // 通知対象者全選択・全解除
  container.querySelector('#select-all-btn').addEventListener('click', function() {
    const checkboxes = container.querySelectorAll('.notification-target');
    checkboxes.forEach(cb => cb.checked = true);
  });

  container.querySelector('#deselect-all-btn').addEventListener('click', function() {
    const checkboxes = container.querySelectorAll('.notification-target');
    checkboxes.forEach(cb => cb.checked = false);
  });

  // 変更内容確認
  container.querySelector('#confirm-btn').addEventListener('click', function() {
    if (!validateForm()) return;

    const selectedTargets = Array.from(container.querySelectorAll('.notification-target:checked'))
      .map(cb => cb.nextSibling.textContent.trim());

    const confirmationContent = `
      <div style="margin-bottom: 8px;"><strong>申請書類:</strong> ${applicationSelect.options[applicationSelect.selectedIndex].text}</div>
      <div style="margin-bottom: 8px;"><strong>新しい処理ルート:</strong> ${newRouteSelect.options[newRouteSelect.selectedIndex].text}</div>
      <div style="margin-bottom: 8px;"><strong>変更理由:</strong> ${changeReasonTextarea.value}</div>
      <div style="margin-bottom: 8px;"><strong>通知対象者:</strong> ${selectedTargets.join(', ')}</div>
      <div><strong>通知メッセージ:</strong> ${notificationMessage.value}</div>
    `;

    container.querySelector('#confirmation-content').innerHTML = confirmationContent;
    confirmationModal.style.display = 'flex';
  });

  // モーダル操作
  container.querySelector('#modal-cancel-btn').addEventListener('click', function() {
    confirmationModal.style.display = 'none';
  });

  container.querySelector('#modal-execute-btn').addEventListener('click', async function() {
    confirmationModal.style.display = 'none';
    await executeRouteChange();
  });

  // バリデーション
  function validateForm() {
    if (!applicationSelect.value) {
      showError('申請書類を選択してください');
      return false;
    }
    if (!newRouteSelect.value) {
      showError('新しい処理ルートを選択してください');
      return false;
    }
    if (!changeReasonTextarea.value.trim()) {
      showError('変更理由を入力してください');
      return false;
    }
    return true;
  }

  // 処理ルート変更実行
  async function executeRouteChange() {
    try {
      // 処理ルート更新
      const routeData = {
        申請書類ID: applicationSelect.value,
        承認フロー定義ID: newRouteSelect.value,
        現在ステップ番号: 1,
        処理状況: '承認待ち',
        開始日時: new Date().toISOString(),
        優先度: 2,
        自動処理フラグ: false,
        備考: changeReasonTextarea.value,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      const savedRoute = await window.aivicApi.save(ROUTE_TABLE, routeData);
      if (savedRoute) {
        alert('処理ルートの変更が完了しました');
        // フォームリセット
        resetForm();
      }
    } catch (error) {
      showError('処理ルートの変更に失敗しました');
    }
  }

  // 処理ルート変更実行ボタン
  container.querySelector('#execute-btn').addEventListener('click', async function() {
    if (!validateForm()) return;
    await executeRouteChange();
  });

  // 通知送信
  container.querySelector('#send-notification-btn').addEventListener('click', async function() {
    const selectedTargets = container.querySelectorAll('.notification-target:checked');
    if (selectedTargets.length === 0) {
      showError('通知対象者を選択してください');
      return;
    }
    if (!notificationMessage.value.trim()) {
      showError('通知メッセージを入力してください');
      return;
    }

    try {
      // 通知履歴保存
      for (const target of selectedTargets) {
        const notificationData = {
          申請書類ID: applicationSelect.value,
          通知対象ユーザーID: target.value,
          通知種別: '処理ルート変更',
          通知タイトル: '処理ルート変更のお知らせ',
          通知内容: notificationMessage.value,
          送信方法: 'システム内通知',
          送信状態: '送信完了',
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0,
          作成者ID: 'current-user-id'
        };

        await window.aivicApi.save(NOTIFICATION_TABLE, notificationData);
      }

      alert('通知の送信が完了しました');
      notificationMessage.value = '';
      messageCharCount.textContent = '0';
    } catch (error) {
      showError('通知の送信に失敗しました');
    }
  });

  // キャンセル
  container.querySelector('#cancel-btn').addEventListener('click', function() {
    if (confirm('入力内容がクリアされます。よろしいですか？')) {
      resetForm();
    }
  });

  // フォームリセット
  function resetForm() {
    applicationSelect.value = '';
    newRouteSelect.value = '';
    changeReasonTextarea.value = '';
    notificationMessage.value = '';
    reasonCharCount.textContent = '0';
    messageCharCount.textContent = '0';
    currentRouteDisplay.textContent = '申請書類を選択すると現在の処理ルートが表示されます';
    renderApprovalSteps([]);
    container.querySelectorAll('.notification-target').forEach(cb => cb.checked = false);
    currentApplicationData = null;
    currentApprovalSteps = [];
  }

  // 承認者変更ボタンのイベントデリゲーション
  container.addEventListener('click', function(e) {
    const changeBtn = e.target.closest('.change-approver-btn');
    if (changeBtn) {
      const stepId = changeBtn.dataset.stepId;
      // 承認者変更処理（簡易実装）
      alert('承認者変更機能は別画面で実装されます');
    }
  });

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const applications = await window.aivicApi.list(APPLICATION_TABLE);
      if (applications && applications.length > 0) {
        // 申請書類選択肢を動的更新
        const additionalOptions = applications.slice(0, 3).map(app => 
          `<option value="${app.id}">${app.申請種別} - ${app.申請タイトル}</option>`
        ).join('');

        applicationSelect.innerHTML = applicationSelect.innerHTML + additionalOptions;
      }
    } catch (error) {
      console.error('初期データの読み込みに失敗:', error);
    }
  }

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 現在の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#application-date').value = today;

  // 文字数カウンター
  function setupCharCounter(textareaId, counterId) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${counterId}`);

    textarea.addEventListener('input', () => {
      counter.textContent = textarea.value.length;
    });
  }

  setupCharCounter('content', 'content-count');
  setupCharCounter('reason', 'reason-count');

  // ファイル選択処理
  const fileInput = container.querySelector('#attachment');
  const fileSelectBtn = container.querySelector('#file-select-btn');
  const fileList = container.querySelector('#file-list');

  fileSelectBtn.addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    fileList.innerHTML = '';

    files.forEach((file, index) => {
      const fileItem = document.createElement('div');
      fileItem.style.cssText = 'display: flex; justify-content: space-between; align-items: center; padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.1);';

      const fileName = document.createElement('span');
      fileName.textContent = `${file.name} (${(file.size / 1024 / 1024).toFixed(2)}MB)`;
      fileName.style.cssText = 'font-size: 12px; color: var(--text);';

      const removeBtn = document.createElement('button');
      removeBtn.textContent = '削除';
      removeBtn.style.cssText = 'background: transparent; color: var(--text-muted); border: none; font-size: 11px; cursor: pointer; padding: 2px 6px;';
      removeBtn.addEventListener('click', () => {
        const dt = new DataTransfer();
        Array.from(fileInput.files).forEach((f, i) => {
          if (i !== index) dt.items.add(f);
        });
        fileInput.files = dt.files;
        fileInput.dispatchEvent(new Event('change'));
      });

      fileItem.appendChild(fileName);
      fileItem.appendChild(removeBtn);
      fileList.appendChild(fileItem);
    });
  });

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション関数
  function validateForm() {
    const title = container.querySelector('#title').value.trim();
    const documentType = container.querySelector('#document-type').value;
    const applicationDate = container.querySelector('#application-date').value;
    const approvalFlow = container.querySelector('#approval-flow').value;
    const content = container.querySelector('#content').value.trim();
    const reason = container.querySelector('#reason').value.trim();
    const urgency = container.querySelector('input[name="urgency"]:checked');
    const amount = container.querySelector('#amount').value;

    // 必須項目チェック
    if (!title) {
      showError('申請書類タイトルを入力してください');
      return false;
    }
    if (title.length > 100) {
      showError('申請書類タイトルは100文字以内で入力してください');
      return false;
    }
    if (!documentType) {
      showError('文書種別を選択してください');
      return false;
    }
    if (!applicationDate) {
      showError('申請日付を選択してください');
      return false;
    }
    if (!approvalFlow) {
      showError('承認フローを選択してください');
      return false;
    }
    if (!content) {
      showError('申請内容詳細を入力してください');
      return false;
    }
    if (content.length > 2000) {
      showError('申請内容詳細は2000文字以内で入力してください');
      return false;
    }
    if (!reason) {
      showError('申請理由を入力してください');
      return false;
    }
    if (reason.length > 1000) {
      showError('申請理由は1000文字以内で入力してください');
      return false;
    }
    if (!urgency) {
      showError('緊急度を選択してください');
      return false;
    }

    // 日付チェック（過去日付禁止）
    const selectedDate = new Date(applicationDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (selectedDate < today) {
      showError('過去の日付は選択できません');
      return false;
    }

    // 金額チェック
    if (amount && (isNaN(amount) || parseFloat(amount) < 0)) {
      showError('申請金額は正の数値を入力してください');
      return false;
    }
    if (amount && parseFloat(amount) > 9999999) {
      showError('申請金額は9,999,999円以下で入力してください');
      return false;
    }

    // ファイルサイズチェック
    const files = Array.from(fileInput.files);
    for (const file of files) {
      if (file.size > 10 * 1024 * 1024) { // 10MB
        showError(`ファイル「${file.name}」のサイズが上限（10MB）を超えています`);
        return false;
      }

      // ファイル形式チェック
      const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.jpg', '.jpeg', '.png'];
      const fileExt = '.' + file.name.split('.').pop().toLowerCase();
      if (!allowedTypes.includes(fileExt)) {
        showError(`ファイル「${file.name}」はサポートされていないファイル形式です。PDF、Word、Excel、画像ファイル（JPG、PNG）のみアップロード可能です。`);
        return false;
      }
    }

    return true;
  }

  // フォーム送信処理
  function submitApplication(isDraft = false) {
    if (!validateForm() && !isDraft) return;

    const formData = {
      申請タイトル: container.querySelector('#title').value.trim(),
      申請種別: container.querySelector('#document-type').value,
      申請内容: container.querySelector('#content').value.trim(),
      申請金額: container.querySelector('#amount').value ? parseInt(container.querySelector('#amount').value) : null,
      申請開始日: container.querySelector('#application-date').value,
      申請終了日: container.querySelector('#application-date').value,
      承認状態: isDraft ? '下書き' : '申請中',
      緊急フラグ: container.querySelector('input[name="urgency"]:checked')?.value === 'highest',
      添付ファイル有無: fileInput.files.length > 0,
      備考: container.querySelector('#reason').value.trim(),
      申請者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      現在承認者ID: null,
      承認段階: 1,
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    // 関連部署の収集
    const selectedDepts = Array.from(container.querySelectorAll('input[name="departments"]:checked'))
      .map(cb => cb.value);
    if (selectedDepts.length > 0) {
      formData.関連部署 = selectedDepts.join(',');
    }

    // 補助金関連度の収集
    const selectedSubsidies = Array.from(container.querySelectorAll('input[name="subsidy-related"]:checked'))
      .map(cb => cb.value);
    if (selectedSubsidies.length > 0) {
      formData.補助金関連 = selectedSubsidies.join(',');
    }

    window.aivicApi.save(1, formData).then(result => {
      if (result) {
        alert(isDraft ? '下書きを保存しました' : '申請書類を作成しました');
        // フォームをリセット
        container.querySelector('#application-form').reset();
        container.querySelector('#application-date').value = today;
        container.querySelector('input[name="urgency"][value="normal"]').checked = true;
        fileList.innerHTML = '';
        container.querySelector('#content-count').textContent = '0';
        container.querySelector('#reason-count').textContent = '0';
      }
    });
  }

  // イベントリスナー
  container.querySelector('#btn-submit').addEventListener('click', (e) => {
    e.preventDefault();
    submitApplication(false);
  });

  container.querySelector('#btn-draft').addEventListener('click', (e) => {
    e.preventDefault();
    submitApplication(true);
  });

  container.querySelector('#btn-upload').addEventListener('click', () => {
    window.showScreen("scr-1779422207222");
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });

  // ホバー効果
  container.querySelector('#btn-submit').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'var(--primary-hover)';
  });
  container.querySelector('#btn-submit').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'var(--primary)';
  });

  const secondaryBtns = container.querySelectorAll('button[style*="transparent"]');
  secondaryBtns.forEach(btn => {
    btn.addEventListener('mouseenter', () => {
      btn.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', () => {
      btn.style.background = 'transparent';
    });
  });
}

function(container, apiUrl, tables) {
  let currentFileData = null;
  let currentAnalysisResult = null;

  // ログ再描画関数
  function renderLogs(logs) {
    const tbody = container.querySelector("#log-tbody");
    if (!logs || logs.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 6px 10px; font-size: 12px; color: var(--text-muted);">処理ログはありません</td></tr>';
      return;
    }
    tbody.innerHTML = logs.map(log => `
      <tr>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${log.実行日時 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${log.処理内容 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${log.結果 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${log.詳細 || ""}</td>
      </tr>
    `).join("");
  }

  // エラー表示関数
  function showError(message) {
    const errorEl = container.querySelector("#error-message");
    errorEl.textContent = message;
    errorEl.style.display = "block";
    setTimeout(() => {
      errorEl.style.display = "none";
    }, 5000);
  }

  // ファイル情報表示
  function displayFileInfo(file) {
    const fileInfoEl = container.querySelector("#file-info");
    const fileNameEl = container.querySelector("#file-name");
    fileNameEl.textContent = `${file.name} (${(file.size / 1024).toFixed(1)} KB)`;
    fileInfoEl.style.display = "block";
  }

  // 文書種別判別処理
  async function analyzeDocument(file) {
    try {
      // ファイル形式チェック
      const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx'];
      const fileExt = '.' + file.name.split('.').pop().toLowerCase();
      if (!allowedTypes.includes(fileExt)) {
        showError("対応していないファイル形式です。PDF、Word、Excelファイルをアップロードしてください。");
        return;
      }

      // ファイルサイズチェック（50MB制限）
      if (file.size > 50 * 1024 * 1024) {
        showError("ファイルサイズが制限を超えています。50MB以下のファイルをアップロードしてください。");
        return;
      }

      // 模擬的な解析処理
      await new Promise(resolve => setTimeout(resolve, 2000)); // 2秒待機

      // 模擬的な判別結果
      const documentTypes = ['申請書', '報告書', '契約書', '稟議書', '請求書', '見積書'];
      const randomType = documentTypes[Math.floor(Math.random() * documentTypes.length)];
      const accuracy = Math.floor(Math.random() * 40) + 60; // 60-99%

      // 結果表示
      container.querySelector("#detected-type").textContent = randomType;
      container.querySelector("#accuracy-score").textContent = `${accuracy}%`;

      // 補助金関連度
      const subsidyLevels = ['低', '中', '高'];
      const subsidyLevel = subsidyLevels[Math.floor(Math.random() * subsidyLevels.length)];
      const subsidyConfidence = Math.floor(Math.random() * 30) + 70;
      container.querySelector("#subsidy-level").textContent = subsidyLevel;
      container.querySelector("#subsidy-confidence").textContent = `${subsidyConfidence}%`;

      // OCR結果
      const sampleOcrText = `文書種別: ${randomType}\n作成日: 2024年1月15日\n申請者: 山田太郎\n内容: ${randomType}に関する申請内容です。\n金額: 100,000円\n承認者: 佐藤次郎`;
      container.querySelector("#ocr-result").textContent = sampleOcrText;

      // キーワード抽出
      const keywords = ['申請', '承認', '金額', '期限', '部署', '責任者'];
      const keywordsHtml = keywords.map(kw => 
        `<span style="display: inline-block; padding: 2px 6px; margin: 2px; background: var(--primary); color: #fff; border-radius: 3px; font-size: 11px;">${kw}</span>`
      ).join('');
      container.querySelector("#keywords-container").innerHTML = keywordsHtml;

      // 承認フロー設定
      container.querySelector("#approval-steps").textContent = "3段階";
      container.querySelector("#current-approver").textContent = "佐藤次郎";
      container.querySelector("#process-status").textContent = "承認待ち";

      // プレビュー表示
      container.querySelector("#document-preview").innerHTML = `
        <div style="text-align: center;">
          <div style="font-size: 14px; color: var(--text); margin-bottom: 8px;">${file.name}</div>
          <div style="font-size: 12px; color: var(--text-muted);">種別: ${randomType}</div>
          <div style="font-size: 12px; color: var(--text-muted);">精度: ${accuracy}%</div>
        </div>
      `;

      currentAnalysisResult = {
        documentType: randomType,
        accuracy: accuracy,
        subsidyLevel: subsidyLevel,
        subsidyConfidence: subsidyConfidence,
        ocrText: sampleOcrText,
        keywords: keywords
      };

      // ログ追加
      addProcessLog("文書種別判別", "成功", `${randomType} (精度: ${accuracy}%)`);

    } catch (error) {
      showError("文書種別判別処理中にエラーが発生しました。");
      addProcessLog("文書種別判別", "失敗", error.message);
    }
  }

  // 処理ログ追加
  function addProcessLog(process, result, detail) {
    const now = new Date().toLocaleString('ja-JP');
    const logData = {
      実行日時: now,
      処理内容: process,
      結果: result,
      詳細: detail
    };

    // 既存ログを取得して新しいログを追加
    window.aivicApi.list(0).then(logs => {
      const updatedLogs = [logData, ...(logs || [])];
      renderLogs(updatedLogs.slice(0, 10)); // 最新10件のみ表示
    });
  }

  // ファイル選択処理
  const fileInput = container.querySelector("#file-input");
  const uploadArea = container.querySelector("#upload-area");

  fileInput.addEventListener("change", (e) => {
    const file = e.target.files[0];
    if (file) {
      currentFileData = file;
      displayFileInfo(file);
      analyzeDocument(file);
    }
  });

  // ドラッグ&ドロップ処理
  uploadArea.addEventListener("dragover", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "var(--primary)";
  });

  uploadArea.addEventListener("dragleave", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "rgba(255,255,255,0.18)";
  });

  uploadArea.addEventListener("drop", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "rgba(255,255,255,0.18)";
    const file = e.dataTransfer.files[0];
    if (file) {
      currentFileData = file;
      fileInput.files = e.dataTransfer.files;
      displayFileInfo(file);
      analyzeDocument(file);
    }
  });

  // 手動種別選択
  container.querySelector("#manual-type").addEventListener("change", (e) => {
    if (e.target.value) {
      container.querySelector("#detected-type").textContent = e.target.value;
      addProcessLog("手動種別選択", "成功", `${e.target.value}に変更`);
    }
  });

  // 再判別実行
  container.querySelector("#btn-reanalyze").addEventListener("click", () => {
    if (!currentFileData) {
      showError("ファイルが選択されていません。");
      return;
    }
    if (confirm("再判別処理を実行しますか？")) {
      analyzeDocument(currentFileData);
    }
  });

  // 判別結果確定
  container.querySelector("#btn-confirm").addEventListener("click", () => {
    if (!currentAnalysisResult) {
      showError("判別結果がありません。ファイルをアップロードして判別処理を実行してください。");
      return;
    }

    const documentType = container.querySelector("#detected-type").textContent;
    if (documentType === "未判別") {
      showError("文書種別が判別されていません。");
      return;
    }

    addProcessLog("判別結果確定", "成功", `文書種別: ${documentType}`);

    // 次画面へ遷移（申請書類登録画面）
    setTimeout(() => {
      window.showScreen('scr-1779422207222');
    }, 1000);
  });

  // 初期ログ表示
  window.aivicApi.list(0).then(logs => {
    renderLogs(logs || []);
  });
}

function(container, apiUrl, tables) {
  let allApplications = [];
  let filteredApplications = [];
  let currentFilter = '';

  // テーブル再描画関数
  function renderApplications(applications) {
    const tbody = container.querySelector('#applications-tbody');
    if (!applications || applications.length === 0) {
      tbody.innerHTML = '<tr><td colspan="11" style="text-align: center; padding: 20px; color: var(--text-muted);">該当する申請が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = applications.map(app => {
      const isDelayed = new Date(app.処理予定日 || app.期限日時) < new Date() && !['承認済', '却下'].includes(app.承認状態);
      const statusClass = getStatusClass(app.承認状態);
      const priorityClass = getPriorityClass(app.優先度);

      return `
        <tr data-id="${app.申請書類ID}" ${isDelayed ? 'class="delay-alert"' : ''}>
          <td style="padding: 6px 10px; font-size: 13px;">${app.申請書類ID?.substring(0, 8) || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${app.申請タイトル || ''}">${app.申請タイトル || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${app.申請者名 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${app.申請種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDate(app.作成日時)}</td>
          <td style="padding: 6px 10px;"><span class="status-badge ${statusClass}">${app.承認状態 || ''}</span></td>
          <td style="padding: 6px 10px; font-size: 13px;">${app.現在承認者名 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDate(app.処理予定日) || '-'}</td>
          <td style="padding: 6px 10px;"><span class="${priorityClass}">${getPriorityText(app.優先度)}</span></td>
          <td style="padding: 6px 10px;">${renderProgress(app.承認段階, app.総承認段数)}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${app.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function getStatusClass(status) {
    const statusMap = {
      '申請中': 'status-pending',
      '承認中': 'status-approving', 
      '承認済': 'status-approved',
      '差戻し': 'status-returned',
      '却下': 'status-rejected'
    };
    return statusMap[status] || 'status-pending';
  }

  function getPriorityClass(priority) {
    if (priority >= 4) return 'priority-high';
    if (priority >= 3) return 'priority-medium';
    return 'priority-low';
  }

  function getPriorityText(priority) {
    if (priority >= 4) return '緊急';
    if (priority >= 3) return '高';
    if (priority >= 2) return '中';
    return '低';
  }

  function renderProgress(current, total) {
    if (!total) return '-';
    const percentage = Math.round((current / total) * 100);
    return `
      <div style="display: flex; align-items: center; gap: 4px;">
        <div style="width: 60px; height: 4px; background: rgba(255,255,255,0.1); border-radius: 2px; overflow: hidden;">
          <div style="width: ${percentage}%; height: 100%; background: var(--primary);"></div>
        </div>
        <span style="font-size: 11px; color: var(--text-muted);">${current}/${total}</span>
      </div>
    `;
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 初期データ読み込み
  async function loadApplications() {
    try {
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      const routes = await window.aivicApi.list(7); // 処理ルートテーブル

      // データを結合
      allApplications = applications.map(app => {
        const applicant = users.find(u => u.ユーザーID === app.申請者ID);
        const currentApprover = users.find(u => u.ユーザーID === app.現在承認者ID);
        const route = routes.find(r => r.申請書類ID === app.申請書類ID);

        return {
          ...app,
          申請者名: applicant?.ユーザー名 || '',
          現在承認者名: currentApprover?.ユーザー名 || '',
          処理予定日: route?.期限日時,
          優先度: route?.優先度 || 2,
          総承認段数: 3 // デフォルト値
        };
      });

      filteredApplications = allApplications;
      renderApplications(filteredApplications);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderApplications([]);
    }
  }

  // 検索機能
  function performSearch() {
    const applicationId = container.querySelector('#input-application-id').value.toLowerCase();
    const applicantName = container.querySelector('#input-applicant-name').value.toLowerCase();
    const documentType = container.querySelector('#select-document-type').value;

    filteredApplications = allApplications.filter(app => {
      const matchId = !applicationId || (app.申請書類ID || '').toLowerCase().includes(applicationId);
      const matchName = !applicantName || (app.申請者名 || '').toLowerCase().includes(applicantName);
      const matchType = !documentType || app.申請種別 === documentType;
      const matchStatus = !currentFilter || app.承認状態 === currentFilter;

      return matchId && matchName && matchType && matchStatus;
    });

    renderApplications(filteredApplications);
  }

  // ステータスタブ機能
  function setupStatusTabs() {
    const tabs = container.querySelectorAll('.status-tab');
    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        // アクティブタブの切り替え
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        currentFilter = tab.dataset.status;
        performSearch();
      });
    });
  }

  // 詳細モーダル表示
  async function showApplicationDetail(applicationId) {
    try {
      const app = allApplications.find(a => a.申請書類ID === applicationId);
      if (!app) {
        alert('申請が見つかりません');
        return;
      }

      // 基本情報表示
      container.querySelector('#detail-id').textContent = app.申請書類ID;
      container.querySelector('#detail-title').textContent = app.申請タイトル || '';
      container.querySelector('#detail-applicant').textContent = app.申請者名 || '';
      container.querySelector('#detail-type').textContent = app.申請種別 || '';
      container.querySelector('#current-approver').textContent = app.現在承認者名 || '承認完了';

      // 承認フロー進捗表示
      renderApprovalFlow(app);

      // 承認履歴表示
      await renderApprovalHistory(applicationId);

      // モーダル表示
      container.querySelector('#detail-modal').style.display = 'block';
    } catch (error) {
      console.error('詳細表示エラー:', error);
      alert('詳細情報の取得に失敗しました');
    }
  }

  function renderApprovalFlow(app) {
    const flowContainer = container.querySelector('#approval-flow');
    const steps = ['申請', '一次承認', '最終承認'];
    const currentStep = app.承認段階 || 1;

    let flowHtml = '';
    steps.forEach((step, index) => {
      const stepNum = index + 1;
      let stepClass = 'progress-pending';

      if (stepNum < currentStep) stepClass = 'progress-completed';
      else if (stepNum === currentStep) stepClass = 'progress-current';

      flowHtml += `
        <div class="progress-step">
          <div class="progress-circle ${stepClass}">${stepNum}</div>
          <span style="font-size: 11px; color: var(--text-muted);">${step}</span>
        </div>
      `;

      if (index < steps.length - 1) {
        const lineClass = stepNum < currentStep ? 'completed' : '';
        flowHtml += `<div class="progress-line ${lineClass}"></div>`;
      }
    });

    flowContainer.innerHTML = flowHtml;
  }

  async function renderApprovalHistory(applicationId) {
    try {
      const histories = await window.aivicApi.list(5); // 承認履歴テーブル
      const users = await window.aivicApi.list(0); // ユーザーテーブル

      const appHistories = histories
        .filter(h => h.申請書類ID === applicationId)
        .sort((a, b) => new Date(b.承認日時) - new Date(a.承認日時));

      const tbody = container.querySelector('#approval-history-tbody');

      if (appHistories.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 12px; color: var(--text-muted);">承認履歴がありません</td></tr>';
        return;
      }

      tbody.innerHTML = appHistories.map(history => {
        const approver = users.find(u => u.ユーザーID === history.承認者ID);
        return `
          <tr>
            <td style="padding: 6px 10px; font-size: 12px;">${approver?.ユーザー名 || ''}</td>
            <td style="padding: 6px 10px; font-size: 12px;">${history.承認結果 || ''}</td>
            <td style="padding: 6px 10px; font-size: 12px;">${formatDate(history.承認日時)}</td>
            <td style="padding: 6px 10px; font-size: 12px;">${history.承認コメント || '-'}</td>
          </tr>
        `;
      }).join('');
    } catch (error) {
      console.error('承認履歴取得エラー:', error);
    }
  }

  // CSVエクスポート機能
  function exportToCSV() {
    const headers = ['申請ID', '申請タイトル', '申請者', '申請種別', '申請日', 'ステータス', '現在承認者', '処理予定日', '優先度'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredApplications.map(app => [
        app.申請書類ID || '',
        `"${(app.申請タイトル || '').replace(/"/g, '""')}"`,
        app.申請者名 || '',
        app.申請種別 || '',
        formatDate(app.作成日時),
        app.承認状態 || '',
        app.現在承認者名 || '',
        formatDate(app.処理予定日) || '',
        getPriorityText(app.優先度)
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `申請進捗_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#input-application-id').value = '';
    container.querySelector('#input-applicant-name').value = '';
    container.querySelector('#select-document-type').value = '';
    currentFilter = '';

    // タブリセット
    container.querySelectorAll('.status-tab').forEach(tab => {
      tab.classList.remove('active');
      if (tab.dataset.status === '') tab.classList.add('active');
    });

    performSearch();
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportToCSV);

  container.querySelector('#btn-back-to-list').addEventListener('click', () => {
    window.showScreen("scr-1779422241190");
  });

  container.querySelector('#btn-document-check').addEventListener('click', () => {
    window.showScreen("scr-1779422434952");
  });

  // モーダル制御
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-close-detail').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const applicationId = detailBtn.dataset.id;
      await showApplicationDetail(applicationId);
    }
  });

  // 初期化
  setupStatusTabs();
  loadApplications();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const resultCount = container.querySelector("#result-count");
  const errorMessage = container.querySelector("#error-message");
  const thresholdSlider = container.querySelector("#threshold-slider");
  const thresholdValue = container.querySelector("#threshold-value");

  // 滞留日数計算関数
  function calculateStagnantDays(createdDate) {
    const created = new Date(createdDate);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  // 緊急度表示関数
  function getPriorityBadge(priority) {
    const colors = {
      1: { bg: 'rgba(34, 197, 94, 0.1)', text: '#22c55e', label: '低' },
      2: { bg: 'rgba(251, 191, 36, 0.1)', text: '#fbbf24', label: '中' },
      3: { bg: 'rgba(239, 68, 68, 0.1)', text: '#ef4444', label: '高' },
      4: { bg: 'rgba(220, 38, 38, 0.1)', text: '#dc2626', label: '緊急' }
    };
    const p = colors[priority] || colors[2];
    return `<span style="background: ${p.bg}; color: ${p.text}; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${p.label}</span>`;
  }

  // ユーザー名取得関数
  function getUserName(userId) {
    if (!userId) return '-';
    const user = tables[0]?.records?.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : userId;
  }

  // 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">該当する滞留案件はありません</td></tr>';
      resultCount.textContent = '0件';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const stagnantDays = calculateStagnantDays(r.作成日時);
      const applicantName = getUserName(r.申請者ID);
      const currentApproverName = getUserName(r.現在承認者ID);

      return `
        <tr data-id="${r.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請書類ID || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請種別 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${currentApproverName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">第${r.承認段階 || 1}段階</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 500;">${stagnantDays}日</td>
          <td style="padding: 6px 10px;">${getPriorityBadge(r.緊急フラグ ? 4 : 2)}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${r.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
            <button class="action-btn secondary notify-btn" data-id="${r.申請書類ID}" style="font-size: 11px; padding: 4px 8px; margin-left: 4px;">催促</button>
          </td>
        </tr>
      `;
    }).join('');

    resultCount.textContent = `${rows.length}件`;
  }

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 検索条件バリデーション
  function validateSearchConditions() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const applicantName = container.querySelector("#applicant-name").value;
    const documentNumber = container.querySelector("#document-number").value;

    // 日付範囲チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('終了日は開始日以降の日付を入力してください');
      return false;
    }

    // 不正文字列チェック
    const dangerousPatterns = [
      /<script/i,
      /javascript:/i,
      /';.*drop.*table/i,
      /union.*select/i
    ];

    const inputs = [applicantName, documentNumber];
    for (const input of inputs) {
      if (input && dangerousPatterns.some(pattern => pattern.test(input))) {
        showError('不正な文字列が含まれています');
        return false;
      }
      if (input && input.length > 1000) {
        showError('入力文字数が上限を超えています');
        return false;
      }
    }

    return true;
  }

  // フィルタリング関数
  function filterRows(rows) {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const documentType = container.querySelector("#document-type").value;
    const applicantName = container.querySelector("#applicant-name").value;
    const documentNumber = container.querySelector("#document-number").value;
    const assignee = container.querySelector("#assignee").value;
    const threshold = parseInt(container.querySelector("#threshold-slider").value);

    const selectedSteps = [];
    if (container.querySelector("#step-manager").checked) selectedSteps.push("部長承認");
    if (container.querySelector("#step-director").checked) selectedSteps.push("役員承認");
    if (container.querySelector("#step-president").checked) selectedSteps.push("社長承認");

    const selectedPriority = container.querySelector('input[name="priority"]:checked')?.value;

    return rows.filter(row => {
      // 日付範囲フィルタ
      if (startDate) {
        const rowDate = new Date(row.作成日時);
        if (rowDate < new Date(startDate)) return false;
      }
      if (endDate) {
        const rowDate = new Date(row.作成日時);
        if (rowDate > new Date(endDate)) return false;
      }

      // 文書種別フィルタ
      if (documentType && row.申請種別 !== documentType) return false;

      // 申請者名フィルタ（部分一致）
      if (applicantName) {
        const userName = getUserName(row.申請者ID);
        if (!userName.includes(applicantName)) return false;
      }

      // 申請書類番号フィルタ（完全一致）
      if (documentNumber && row.申請書類ID !== documentNumber) return false;

      // 担当者フィルタ
      if (assignee) {
        const currentApprover = getUserName(row.現在承認者ID);
        if (currentApprover !== assignee) return false;
      }

      // 滞留日数閾値フィルタ
      const stagnantDays = calculateStagnantDays(row.作成日時);
      if (stagnantDays < threshold) return false;

      // 承認ステップフィルタ
      if (selectedSteps.length > 0) {
        const currentStep = `第${row.承認段階}段階`;
        // 簡易的なマッピング
        const stepMapping = {
          1: "部長承認",
          2: "役員承認", 
          3: "社長承認"
        };
        const stepName = stepMapping[row.承認段階];
        if (!selectedSteps.includes(stepName)) return false;
      }

      // 緊急度フィルタ
      if (selectedPriority) {
        const rowPriority = row.緊急フラグ ? "高" : "中";
        if (rowPriority !== selectedPriority) return false;
      }

      return true;
    });
  }

  // CSVエクスポート関数
  function exportCSV(rows) {
    const headers = ['申請書類番号', '申請種別', '申請者', '現在承認者', '承認段階', '滞留日数', '緊急度', '作成日時'];
    const csvData = [headers];

    rows.forEach(row => {
      const stagnantDays = calculateStagnantDays(row.作成日時);
      const applicantName = getUserName(row.申請者ID);
      const currentApproverName = getUserName(row.現在承認者ID);
      const priority = row.緊急フラグ ? '高' : '中';

      csvData.push([
        row.申請書類ID || '',
        row.申請種別 || '',
        applicantName,
        currentApproverName,
        `第${row.承認段階 || 1}段階`,
        `${stagnantDays}日`,
        priority,
        row.作成日時 || ''
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `滞留案件一覧_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      renderRows(rows);
    } else {
      renderRows(tables[1]?.records || []);
    }
  });

  // スライダー値更新
  thresholdSlider.addEventListener('input', (e) => {
    thresholdValue.textContent = e.target.value;
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    if (!validateSearchConditions()) return;

    try {
      const allRows = await window.aivicApi.list(1);
      if (allRows) {
        const filteredRows = filterRows(allRows);
        renderRows(filteredRows);
      } else {
        showError('データの取得に失敗しました');
      }
    } catch (error) {
      showError('検索処理中にエラーが発生しました');
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#document-type").value = '';
    container.querySelector("#applicant-name").value = '';
    container.querySelector("#document-number").value = '';
    container.querySelector("#assignee").value = '';
    container.querySelector("#threshold-slider").value = '7';
    thresholdValue.textContent = '7';

    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelectorAll('input[type="radio"]').forEach(rb => rb.checked = false);

    // 全件表示に戻す
    window.aivicApi.list(1).then(rows => {
      if (rows) {
        renderRows(rows);
      } else {
        renderRows(tables[1]?.records || []);
      }
    });
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const allRows = await window.aivicApi.list(1);
      if (allRows) {
        const filteredRows = filterRows(allRows);
        exportCSV(filteredRows);
      } else {
        showError('エクスポートするデータがありません');
      }
    } catch (error) {
      showError('CSVエクスポート中にエラーが発生しました');
    }
  });

  // 行レベル操作（詳細・催促）
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const notifyBtn = e.target.closest(".notify-btn");

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1779422434952"); // 申請書類確認画面
    }

    if (notifyBtn) {
      const id = notifyBtn.dataset.id;
      if (confirm('催促通知を送信しますか？')) {
        window.showScreen("scr-1779422392638"); // 催促通知送信処理
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentSort = { field: null, direction: 'asc' };
  let selectedApplications = new Set();
  let allApplications = [];

  // 緊急度レベルのマッピング
  const urgencyLevels = {
    1: { label: '低', color: '#22c55e' },
    2: { label: '中', color: '#f59e0b' },
    3: { label: '高', color: '#ef4444' },
    4: { label: '緊急', color: '#dc2626' }
  };

  // 遅延申請データを取得・結合する関数
  async function getDelayedApplications() {
    try {
      const applications = await window.aivicApi.list(1); // 申請書類
      const users = await window.aivicApi.list(0); // ユーザー
      const documentTypes = await window.aivicApi.list(2); // 文書種別マスタ
      const approvalSteps = await window.aivicApi.list(4); // 承認ステップ
      const notificationHistory = await window.aivicApi.list(5); // 通知履歴

      if (!applications || !users || !documentTypes || !approvalSteps) {
        return [];
      }

      const now = new Date();
      const delayedApps = [];

      applications.forEach(app => {
        if (app.承認状態 === '申請中' || app.承認状態 === '承認待ち') {
          const createdDate = new Date(app.作成日時);
          const daysDiff = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));

          if (daysDiff > 3) { // 3日以上経過を遅延とする
            const applicant = users.find(u => u.ユーザーID === app.申請者ID);
            const docType = documentTypes.find(d => d.文書種別ID === app.申請種別);
            const currentStep = approvalSteps.find(s => s.申請書類ID === app.申請書類ID && s.承認状態 === '未承認');
            const approver = currentStep ? users.find(u => u.ユーザーID === currentStep.承認者ID) : null;

            // 最後の催促通知から24時間以内かチェック
            const lastNotification = notificationHistory
              .filter(n => n.申請書類ID === app.申請書類ID && n.通知種別 === '催促通知')
              .sort((a, b) => new Date(b.送信日時) - new Date(a.送信日時))[0];

            const canSendReminder = !lastNotification || 
              (new Date() - new Date(lastNotification.送信日時)) > (24 * 60 * 60 * 1000);

            // 緊急度を計算（遅延日数に基づく）
            let urgencyLevel = 1;
            if (daysDiff > 14) urgencyLevel = 4;
            else if (daysDiff > 10) urgencyLevel = 3;
            else if (daysDiff > 7) urgencyLevel = 2;

            delayedApps.push({
              id: app.申請書類ID,
              申請書類番号: app.申請書類ID.substring(0, 8),
              申請者名: applicant ? applicant.ユーザー名 : '不明',
              申請者メール: applicant ? applicant.メールアドレス : '',
              文書種別: docType ? docType.文書種別名 : '不明',
              申請日: createdDate.toLocaleDateString('ja-JP'),
              承認ステップ: currentStep ? `第${currentStep.ステップ番号}段階` : '不明',
              承認者名: approver ? approver.ユーザー名 : '不明',
              承認者メール: approver ? approver.メールアドレス : '',
              遅延日数: daysDiff,
              緊急度: urgencyLevel,
              申請タイトル: app.申請タイトル,
              canSendReminder: canSendReminder,
              lastNotificationCount: notificationHistory.filter(n => 
                n.申請書類ID === app.申請書類ID && n.通知種別 === '催促通知'
              ).length
            });
          }
        }
      });

      return delayedApps;
    } catch (error) {
      console.error('遅延申請データの取得に失敗:', error);
      return [];
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#delayed-applications-tbody');
    if (!tbody) return;

    tbody.innerHTML = rows.map(row => {
      const urgency = urgencyLevels[row.緊急度] || urgencyLevels[1];
      const isDisabled = !row.canSendReminder || !row.承認者メール || row.lastNotificationCount >= 5;

      return `
        <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; font-size: 13px;">
            <input type="checkbox" class="row-checkbox" data-id="${row.id}" 
                   ${isDisabled ? 'disabled' : ''} style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請書類番号}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請者名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.文書種別}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請日}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.承認ステップ}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.承認者名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 500;">
            ${row.遅延日数 >= 30 ? '30日以上' : row.遅延日数 + '日'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="background: ${urgency.color}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">
              ${urgency.label}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn send-reminder-btn" data-id="${row.id}" 
                    ${isDisabled ? 'disabled style="opacity: 0.5; cursor: not-allowed;"' : 'style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;"'}>
              催促送信
            </button>
          </td>
        </tr>
      `;
    }).join('');

    updateStatistics(rows);
    updateSelectAllState();
  }

  // 統計情報更新
  function updateStatistics(rows) {
    const totalElement = container.querySelector('#total-delayed');
    const urgentElement = container.querySelector('#urgent-count');
    const avgElement = container.querySelector('#avg-delay');

    if (totalElement) totalElement.textContent = rows.length;
    if (urgentElement) {
      const urgentCount = rows.filter(r => r.緊急度 >= 3).length;
      urgentElement.textContent = urgentCount;
    }
    if (avgElement && rows.length > 0) {
      const avgDelay = Math.round(rows.reduce((sum, r) => sum + r.遅延日数, 0) / rows.length);
      avgElement.textContent = avgDelay;
    }
  }

  // 全選択チェックボックスの状態更新
  function updateSelectAllState() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const rowCheckboxes = container.querySelectorAll('.row-checkbox:not([disabled])');
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');

    if (selectAllCheckbox && rowCheckboxes.length > 0) {
      selectAllCheckbox.indeterminate = checkedBoxes.length > 0 && checkedBoxes.length < rowCheckboxes.length;
      selectAllCheckbox.checked = checkedBoxes.length === rowCheckboxes.length;
    }
  }

  // ソート機能
  function sortApplications(field) {
    if (currentSort.field === field) {
      currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
    } else {
      currentSort.field = field;
      currentSort.direction = 'asc';
    }

    const sortedApps = [...allApplications].sort((a, b) => {
      let aVal = a[field];
      let bVal = b[field];

      if (field === '遅延日数') {
        aVal = parseInt(aVal);
        bVal = parseInt(bVal);
      }

      if (currentSort.direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    const sortIcon = container.querySelector('#sort-icon');
    if (sortIcon) {
      sortIcon.textContent = currentSort.direction === 'asc' ? '↑' : '↓';
    }

    renderRows(sortedApps);
  }

  // フィルタリング機能
  function filterApplications() {
    const urgencyFilter = container.querySelector('#urgency-filter').value;
    let filtered = allApplications;

    if (urgencyFilter) {
      filtered = filtered.filter(app => app.緊急度.toString() === urgencyFilter);
    }

    renderRows(filtered);
  }

  // 催促通知送信処理
  async function sendReminderNotification(applicationIds, isBulk = false) {
    try {
      const applications = applicationIds.map(id => 
        allApplications.find(app => app.id === id)
      ).filter(Boolean);

      if (applications.length === 0) {
        showError('送信対象の申請が見つかりません');
        return;
      }

      // メールアドレス未設定チェック
      const noEmailApps = applications.filter(app => !app.承認者メール);
      if (noEmailApps.length > 0) {
        showError(`承認者のメールアドレスが設定されていない申請があります: ${noEmailApps.map(a => a.申請書類番号).join(', ')}`);
        return;
      }

      // 送信履歴上限チェック
      const maxHistoryApps = applications.filter(app => app.lastNotificationCount >= 5);
      if (maxHistoryApps.length > 0) {
        showError(`送信履歴が上限に達している申請があります: ${maxHistoryApps.map(a => a.申請書類番号).join(', ')}`);
        return;
      }

      // 通知履歴に記録
      for (const app of applications) {
        const notificationData = {
          申請書類ID: app.id,
          通知対象ユーザーID: app.承認者ID,
          通知種別: '催促通知',
          通知タイトル: `【催促】申請書類の承認をお願いします - ${app.申請タイトル}`,
          通知内容: `申請書類番号: ${app.申請書類番号}\n申請者: ${app.申請者名}\n遅延日数: ${app.遅延日数}日\n\n承認処理をお願いいたします。`,
          送信方法: 'メール',
          送信先アドレス: app.承認者メール,
          送信状態: '送信完了',
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user-id'
        };

        await window.aivicApi.save(5, notificationData);
      }

      showSuccess(`催促通知を${applications.length}件送信しました`);

      // データを再読み込み
      await loadDelayedApplications();

    } catch (error) {
      console.error('催促通知送信エラー:', error);
      showError('催促通知の送信に失敗しました');
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    if (errorEl) {
      errorEl.textContent = message;
      errorEl.style.display = 'block';
      setTimeout(() => {
        errorEl.style.display = 'none';
      }, 5000);
    }
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successEl = container.querySelector('#success-message');
    if (successEl) {
      successEl.textContent = message;
      successEl.style.display = 'block';
      setTimeout(() => {
        successEl.style.display = 'none';
      }, 3000);
    }
  }

  // モーダル表示/非表示
  function showModal(content) {
    const modal = container.querySelector('#reminder-modal');
    const contentEl = container.querySelector('#reminder-content');
    if (modal && contentEl) {
      contentEl.innerHTML = content;
      modal.style.display = 'flex';
    }
  }

  function hideModal() {
    const modal = container.querySelector('#reminder-modal');
    if (modal) {
      modal.style.display = 'none';
    }
  }

  // CSVエクスポート
  function exportToCSV() {
    const headers = ['申請書類番号', '申請者名', '文書種別', '申請日', '承認ステップ', '承認者名', '遅延日数', '緊急度'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allApplications.map(row => [
        row.申請書類番号,
        row.申請者名,
        row.文書種別,
        row.申請日,
        row.承認ステップ,
        row.承認者名,
        row.遅延日数,
        urgencyLevels[row.緊急度].label
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `遅延申請一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 遅延申請データ読み込み
  async function loadDelayedApplications() {
    allApplications = await getDelayedApplications();
    renderRows(allApplications);
  }

  // 初期データ読み込み
  loadDelayedApplications();

  // イベントリスナー設定

  // 緊急度フィルター
  container.querySelector('#urgency-filter').addEventListener('change', filterApplications);

  // ソート
  container.querySelector('#sort-delay-days').addEventListener('click', () => {
    sortApplications('遅延日数');
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox:not([disabled])');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
    });
    updateSelectAllState();
  });

  // 一括催促送信
  container.querySelector('#btn-bulk-reminder').addEventListener('click', () => {
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    if (checkedBoxes.length === 0) {
      showError('送信対象の申請を選択してください');
      return;
    }

    const selectedIds = Array.from(checkedBoxes).map(cb => cb.dataset.id);
    const selectedApps = selectedIds.map(id => allApplications.find(app => app.id === id));

    showModal(`
      <p>以下の${selectedApps.length}件の申請に催促通知を送信しますか？</p>
      <ul style="margin: 8px 0; padding-left: 20px; max-height: 150px; overflow-y: auto;">
        ${selectedApps.map(app => `<li>${app.申請書類番号} - ${app.申請者名}</li>`).join('')}
      </ul>
    `);

    container.querySelector('#btn-confirm-reminder').onclick = () => {
      hideModal();
      sendReminderNotification(selectedIds, true);
    };
  });

  // 通知履歴表示
  container.querySelector('#btn-notification-history').addEventListener('click', () => {
    window.showScreen('scr-1779422306272'); // 承認履歴・通知履歴照会画面
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', exportToCSV);

  // モーダル操作
  container.querySelector('#btn-cancel-reminder').addEventListener('click', hideModal);

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 個別催促送信
    const sendBtn = e.target.closest('.send-reminder-btn');
    if (sendBtn && !sendBtn.disabled) {
      const appId = sendBtn.dataset.id;
      const app = allApplications.find(a => a.id === appId);

      if (app) {
        showModal(`
          <p>以下の申請に催促通知を送信しますか？</p>
          <div style="margin: 12px 0; padding: 12px; background: rgba(255,255,255,0.05); border-radius: 6px;">
            <div><strong>申請書類番号:</strong> ${app.申請書類番号}</div>
            <div><strong>申請者:</strong> ${app.申請者名}</div>
            <div><strong>承認者:</strong> ${app.承認者名}</div>
            <div><strong>遅延日数:</strong> ${app.遅延日数}日</div>
          </div>
        `);

        container.querySelector('#btn-confirm-reminder').onclick = () => {
          hideModal();
          sendReminderNotification([appId]);
        };
      }
    }

    // 行チェックボックス
    const checkbox = e.target.closest('.row-checkbox');
    if (checkbox) {
      updateSelectAllState();
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#reminder-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      hideModal();
    }
  });
}

function(container, apiUrl, tables) {
  let allNotifications = [];
  let currentUser = null;

  // 現在のユーザー情報を取得（承認者として）
  async function getCurrentUser() {
    try {
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      return users.find(u => u.権限レベル >= 2) || users[0]; // 承認者権限のユーザーまたは最初のユーザー
    } catch (error) {
      console.error('ユーザー情報取得エラー:', error);
      return null;
    }
  }

  // 緊急度アイコンを取得
  function getPriorityIcon(priority) {
    switch(priority) {
      case 4: return '🔴';
      case 3: return '🟠';
      case 2: return '🟡';
      case 1: return '🟢';
      default: return '⚪';
    }
  }

  // 緊急度テキストを取得
  function getPriorityText(priority) {
    switch(priority) {
      case 4: return '緊急';
      case 3: return '高';
      case 2: return '中';
      case 1: return '低';
      default: return '未設定';
    }
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP') + ' ' + date.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
  }

  // 期限チェック
  function isOverdue(deadline) {
    if (!deadline) return false;
    return new Date(deadline) < new Date();
  }

  // 期限が近いかチェック
  function isNearDeadline(deadline, days = 3) {
    if (!deadline) return false;
    const deadlineDate = new Date(deadline);
    const now = new Date();
    const diffTime = deadlineDate - now;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays <= days && diffDays >= 0;
  }

  // 通知データを構築
  async function buildNotifications() {
    try {
      const [applications, users, approvalSteps, notifications] = await Promise.all([
        window.aivicApi.list(1), // 申請書類
        window.aivicApi.list(0), // ユーザー
        window.aivicApi.list(4), // 承認ステップ
        window.aivicApi.list(5)  // 通知履歴
      ]);

      if (!currentUser) return [];

      // 現在のユーザーが承認者となっている承認待ちの案件を取得
      const pendingSteps = approvalSteps.filter(step => 
        step.承認者ID === currentUser.ユーザーID && 
        step.承認状態 === '未承認'
      );

      const notificationData = [];

      for (const step of pendingSteps) {
        const application = applications.find(app => app.申請書類ID === step.申請書類ID);
        const applicant = users.find(u => u.ユーザーID === application?.申請者ID);
        const notification = notifications.find(n => 
          n.承認ステップID === step.承認ステップID && 
          n.通知対象ユーザーID === currentUser.ユーザーID
        );

        if (application && applicant) {
          // 優先度を決定（緊急フラグと処理ルートの優先度から）
          let priority = 2; // デフォルト中
          if (application.緊急フラグ) {
            priority = 4; // 緊急
          }

          notificationData.push({
            id: step.承認ステップID,
            申請書類ID: application.申請書類ID,
            申請書類名: application.申請タイトル,
            申請者名: applicant.ユーザー名,
            申請種別: application.申請種別,
            緊急度: priority,
            通知日時: notification?.送信日時 || step.作成日時,
            承認期限: step.期限日時,
            既読フラグ: notification?.既読フラグ || false,
            承認状態: step.承認状態
          });
        }
      }

      return notificationData.sort((a, b) => {
        // 緊急度順、次に期限順でソート
        if (a.緊急度 !== b.緊急度) return b.緊急度 - a.緊急度;
        if (a.承認期限 && b.承認期限) {
          return new Date(a.承認期限) - new Date(b.承認期限);
        }
        return new Date(b.通知日時) - new Date(a.通知日時);
      });

    } catch (error) {
      console.error('通知データ構築エラー:', error);
      showError('データの取得に失敗しました');
      return [];
    }
  }

  // 申請者フィルターの選択肢を更新
  function updateApplicantFilter(notifications) {
    const applicantFilter = container.querySelector('#filter-applicant');
    const applicants = [...new Set(notifications.map(n => n.申請者名))].sort();

    // 既存のオプション（「すべて」以外）をクリア
    while (applicantFilter.children.length > 1) {
      applicantFilter.removeChild(applicantFilter.lastChild);
    }

    // 申請者を追加
    applicants.forEach(applicant => {
      const option = document.createElement('option');
      option.value = applicant;
      option.textContent = applicant;
      applicantFilter.appendChild(option);
    });
  }

  // 未読件数バッジを更新
  function updateUnreadBadge(notifications) {
    const badge = container.querySelector('#unread-badge');
    const unreadCount = notifications.filter(n => !n.既読フラグ).length;

    if (unreadCount > 0) {
      badge.textContent = unreadCount;
      badge.style.display = 'block';
    } else {
      badge.style.display = 'none';
    }
  }

  // 遅延警告を更新
  function updateDelayAlert(notifications) {
    const alert = container.querySelector('#delay-alert');
    const message = container.querySelector('#delay-message');

    const overdueCount = notifications.filter(n => isOverdue(n.承認期限)).length;
    const nearDeadlineCount = notifications.filter(n => isNearDeadline(n.承認期限)).length;

    if (overdueCount > 0 || nearDeadlineCount > 0) {
      let alertText = '';
      if (overdueCount > 0) {
        alertText += `承認期限を過ぎた案件が${overdueCount}件あります。`;
      }
      if (nearDeadlineCount > 0) {
        if (alertText) alertText += ' ';
        alertText += `承認期限が近い案件が${nearDeadlineCount}件あります。`;
      }

      message.textContent = alertText;
      alert.style.display = 'block';
    } else {
      alert.style.display = 'none';
    }
  }

  // 通知一覧を描画
  function renderNotifications(notifications) {
    const tbody = container.querySelector('#notifications-tbody');
    const emptyMessage = container.querySelector('#empty-message');

    if (notifications.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.style.display = 'block';
      return;
    }

    emptyMessage.style.display = 'none';

    tbody.innerHTML = notifications.map(notification => {
      const isUnread = !notification.既読フラグ;
      const overdue = isOverdue(notification.承認期限);
      const nearDeadline = isNearDeadline(notification.承認期限);

      let rowStyle = '';
      if (isUnread) {
        rowStyle = 'background: rgba(255,255,255,0.03);';
      }
      if (overdue) {
        rowStyle += 'border-left: 3px solid #dc2626;';
      } else if (nearDeadline) {
        rowStyle += 'border-left: 3px solid #ff6a00;';
      }

      return `
        <tr data-id="${notification.id}" style="${rowStyle}">
          <td style="padding: 6px 10px; font-size: 13px;">
            ${isUnread ? '<span style="color: var(--primary); font-weight: 600;">●</span> 未読' : '<span style="color: var(--text-muted);">○</span> 既読'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            ${getPriorityIcon(notification.緊急度)} ${getPriorityText(notification.緊急度)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <a href="#" class="document-link" data-id="${notification.申請書類ID}" style="color: var(--primary); text-decoration: none; cursor: pointer;">
              ${notification.申請書類名}
            </a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${notification.申請者名}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${notification.申請種別}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text-muted);">
            ${formatDateTime(notification.通知日時)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: ${overdue ? '#dc2626' : nearDeadline ? '#ff6a00' : 'var(--text)'};">
            ${notification.承認期限 ? formatDateTime(notification.承認期限) : '期限なし'}
            ${overdue ? ' (期限超過)' : nearDeadline ? ' (期限間近)' : ''}
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn detail-btn" data-id="${notification.申請書類ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">
              案件詳細
            </button>
          </td>
        </tr>
      `;
    }).join('');

    updateUnreadBadge(notifications);
    updateDelayAlert(notifications);
  }

  // フィルター適用
  function applyFilters() {
    const priorityFilter = container.querySelector('#filter-priority').value;
    const documentTypeFilter = container.querySelector('#filter-document-type').value;
    const applicantFilter = container.querySelector('#filter-applicant').value;
    const deadlineFilter = container.querySelector('#filter-deadline').value;

    let filtered = allNotifications;

    if (priorityFilter) {
      filtered = filtered.filter(n => n.緊急度.toString() === priorityFilter);
    }

    if (documentTypeFilter) {
      filtered = filtered.filter(n => n.申請種別 === documentTypeFilter);
    }

    if (applicantFilter) {
      filtered = filtered.filter(n => n.申請者名 === applicantFilter);
    }

    if (deadlineFilter) {
      const now = new Date();
      filtered = filtered.filter(n => {
        if (!n.承認期限) return false;
        const deadline = new Date(n.承認期限);

        switch (deadlineFilter) {
          case 'today':
            return deadline.toDateString() === now.toDateString();
          case 'week':
            const weekLater = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
            return deadline <= weekLater;
          case 'month':
            const monthLater = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
            return deadline <= monthLater;
          case 'overdue':
            return deadline < now;
          default:
            return true;
        }
      });
    }

    renderNotifications(filtered);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.style.display = 'block';

    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 通知を既読にする
  async function markAsRead(notificationId) {
    try {
      const notifications = await window.aivicApi.list(5);
      const notification = notifications.find(n => n.承認ステップID === notificationId);

      if (notification && !notification.既読フラグ) {
        await window.aivicApi.update(5, notification.通知履歴ID, {
          既読フラグ: true,
          既読日時: new Date().toISOString()
        });

        // ローカルデータも更新
        const localNotification = allNotifications.find(n => n.id === notificationId);
        if (localNotification) {
          localNotification.既読フラグ = true;
        }
      }
    } catch (error) {
      console.error('既読更新エラー:', error);
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      currentUser = await getCurrentUser();
      if (!currentUser) {
        showError('ユーザー情報を取得できませんでした');
        return;
      }

      allNotifications = await buildNotifications();
      updateApplicantFilter(allNotifications);
      renderNotifications(allNotifications);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの取得に失敗しました');
    }
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-refresh').addEventListener('click', loadData);

  // 申請書類リンククリック
  container.addEventListener('click', async (e) => {
    const documentLink = e.target.closest('.document-link');
    if (documentLink) {
      e.preventDefault();
      const applicationId = documentLink.dataset.id;
      const notificationId = e.target.closest('tr').dataset.id;

      try {
        // 既読にする
        await markAsRead(notificationId);

        // 詳細画面に遷移
        window.showScreen("scr-1779422434952");
      } catch (error) {
        console.error('申請書類リンクエラー:', error);
        showError('申請書類が見つかりません');
      }
    }

    // 案件詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const applicationId = detailBtn.dataset.id;
      const notificationId = e.target.closest('tr').dataset.id;

      try {
        // 既読にする
        await markAsRead(notificationId);

        // 詳細画面に遷移
        window.showScreen("scr-1779422434952");
      } catch (error) {
        console.error('案件詳細エラー:', error);
        showError('申請書類が見つかりません');
      }
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  // 現在の申請書類データ
  let currentApplication = null;

  // 初期データの設定
  function loadApplicationData() {
    // 申請書類テーブルから最初のレコードを取得
    const applications = tables.find(t => t.tableName === '申請書類')?.records || [];
    if (applications.length > 0) {
      currentApplication = applications[0];
      displayApplicationInfo(currentApplication);
    }

    // 承認履歴の表示
    loadApprovalHistory();
  }

  // 申請情報の表示
  function displayApplicationInfo(app) {
    const users = tables.find(t => t.tableName === 'ユーザー')?.records || [];
    const docTypes = tables.find(t => t.tableName === '文書種別マスタ')?.records || [];

    const applicant = users.find(u => u.ユーザーID === app.申請者ID);
    const docType = docTypes.find(d => d.文書種別ID === app.申請種別);

    container.querySelector('#application-id').textContent = app.申請書類ID || 'APP-2024-001';
    container.querySelector('#applicant-name').textContent = applicant?.ユーザー名 || '田中 太郎';
    container.querySelector('#applicant-department').textContent = applicant?.所属部署 || '営業部';
    container.querySelector('#document-type').textContent = docType?.文書種別名 || app.申請種別 || '経費申請';
    container.querySelector('#application-date').textContent = app.作成日時 ? new Date(app.作成日時).toLocaleString('ja-JP') : '2024-01-15 10:30';
    container.querySelector('#application-title').textContent = app.申請タイトル || '出張交通費申請';
    container.querySelector('#application-content').textContent = app.申請内容 || '東京出張に伴う交通費の申請です。';

    // 申請金額の表示
    if (app.申請金額) {
      container.querySelector('#application-amount').textContent = `¥${app.申請金額.toLocaleString()}`;
    }

    // 緊急フラグの表示
    const urgentFlag = container.querySelector('#urgent-flag');
    if (app.緊急フラグ) {
      urgentFlag.innerHTML = '<span style="background: #ff6a00; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">緊急</span>';
    } else {
      urgentFlag.innerHTML = '<span style="background: rgba(255,255,255,0.18); color: var(--text-muted); padding: 2px 6px; border-radius: 4px; font-size: 11px;">通常</span>';
    }

    // 添付ファイルの表示
    displayAttachments(app.添付ファイル有無);
  }

  // 添付ファイルの表示
  function displayAttachments(hasAttachments) {
    const attachmentList = container.querySelector('#attachment-list');
    const noAttachments = container.querySelector('#no-attachments');

    if (hasAttachments) {
      attachmentList.style.display = 'block';
      noAttachments.style.display = 'none';
    } else {
      attachmentList.style.display = 'none';
      noAttachments.style.display = 'block';
    }
  }

  // 承認履歴の読み込み
  function loadApprovalHistory() {
    const histories = tables.find(t => t.tableName === '承認履歴')?.records || [];
    const users = tables.find(t => t.tableName === 'ユーザー')?.records || [];
    const tbody = container.querySelector('#approval-history-tbody');
    const noHistory = container.querySelector('#no-approval-history');

    if (histories.length === 0) {
      tbody.style.display = 'none';
      noHistory.style.display = 'block';
      return;
    }

    tbody.style.display = '';
    noHistory.style.display = 'none';

    tbody.innerHTML = histories.map(history => {
      const approver = users.find(u => u.ユーザーID === history.承認者ID);
      const statusColor = getStatusColor(history.承認結果);

      return `
        <tr>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${approver?.ユーザー名 || '不明'}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">
            <span style="background: ${statusColor}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${history.承認結果}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${history.承認日時 ? new Date(history.承認日時).toLocaleString('ja-JP') : '-'}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${history.承認コメント || '-'}</td>
        </tr>
      `;
    }).join('');
  }

  // ステータス色の取得
  function getStatusColor(status) {
    switch (status) {
      case '承認': case '承認済': return 'var(--primary)';
      case '差戻し': return '#ff6a00';
      case '却下': return '#dc3545';
      case '申請': return '#6c757d';
      default: return '#6c757d';
    }
  }

  // コメント文字数カウント
  const commentTextarea = container.querySelector('#approval-comment');
  const commentCount = container.querySelector('#comment-count');

  commentTextarea.addEventListener('input', function() {
    const length = this.value.length;
    commentCount.textContent = length;

    if (length > 500) {
      this.value = this.value.substring(0, 500);
      commentCount.textContent = 500;
    }
  });

  // 判断選択の変更時処理
  const decisionRadios = container.querySelectorAll('input[name="approval-decision"]');
  const commentRequired = container.querySelector('#comment-required');

  decisionRadios.forEach(radio => {
    radio.addEventListener('change', function() {
      if (this.value === 'reject' || this.value === 'deny') {
        commentRequired.style.display = 'inline';
      } else {
        commentRequired.style.display = 'none';
      }
    });
  });

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorSpan = errorDiv.querySelector('span');
    errorSpan.textContent = message;
    errorDiv.style.display = 'block';

    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const selectedDecision = container.querySelector('input[name="approval-decision"]:checked');
    const comment = commentTextarea.value.trim();

    if (!selectedDecision) {
      showError('承認判断を選択してください');
      return false;
    }

    if ((selectedDecision.value === 'reject' || selectedDecision.value === 'deny') && !comment) {
      showError('差戻し・却下の場合はコメントの入力が必須です');
      return false;
    }

    if (comment.length < 5 && comment.length > 0) {
      showError('コメントは5文字以上で入力してください');
      return false;
    }

    return true;
  }

  // 判断確定ボタンのイベント
  container.querySelector('[data-testid="submit-decision-button"]').addEventListener('click', async function() {
    if (!validateForm()) return;

    if (!confirm('承認判断を確定しますか？')) return;

    const selectedDecision = container.querySelector('input[name="approval-decision"]:checked');
    const comment = commentTextarea.value.trim();
    const isConditional = container.querySelector('#conditional-approval').checked;

    try {
      // 承認履歴に記録
      const historyData = {
        申請書類ID: currentApplication?.申請書類ID,
        承認ステップID: 'step-001', // 実際は現在のステップIDを使用
        承認者ID: 'current-user-id', // 実際は現在のユーザーIDを使用
        承認結果: selectedDecision.value === 'approve' ? (isConditional ? '条件付き承認' : '承認') : 
                 selectedDecision.value === 'reject' ? '差戻し' : '却下',
        承認コメント: comment,
        承認日時: new Date().toISOString(),
        承認順序: 1,
        代理承認フラグ: false
      };

      const historyTableIndex = tables.findIndex(t => t.tableName === '承認履歴');
      if (historyTableIndex >= 0) {
        await window.aivicApi.save(historyTableIndex, historyData);
      }

      // 申請書類のステータス更新
      if (currentApplication) {
        const applicationTableIndex = tables.findIndex(t => t.tableName === '申請書類');
        if (applicationTableIndex >= 0) {
          const updateData = {
            承認状態: historyData.承認結果,
            更新日時: new Date().toISOString()
          };

          await window.aivicApi.update(applicationTableIndex, currentApplication.申請書類ID, updateData);
        }
      }

      // 結果通知処理画面に遷移
      window.showScreen("scr-1779422470870");

    } catch (error) {
      showError('承認判断の保存に失敗しました');
      console.error('Error saving approval decision:', error);
    }
  });

  // 戻るボタンのイベント
  container.querySelector('[data-testid="back-button"]').addEventListener('click', function() {
    window.showScreen("scr-1779422434952");
  });

  // ファイルプレビューのイベント
  container.addEventListener('click', function(e) {
    if (e.target.matches('[data-testid="preview-file-btn"]')) {
      const modal = container.querySelector('#file-preview-modal');
      const content = container.querySelector('#preview-content');

      content.innerHTML = `
        <div style="padding: 40px; color: var(--text-muted);">
          <div style="font-size: 48px; margin-bottom: 12px;">📄</div>
          <div>ファイルプレビュー機能</div>
          <div style="font-size: 12px; margin-top: 8px;">実際の実装では、ファイルの種類に応じて<br>PDF viewer や画像表示などを行います</div>
        </div>
      `;

      modal.style.display = 'flex';
    }
  });

  // プレビューモーダルを閉じる
  container.querySelector('#close-preview').addEventListener('click', function() {
    container.querySelector('#file-preview-modal').style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#file-preview-modal').addEventListener('click', function(e) {
    if (e.target === this) {
      this.style.display = 'none';
    }
  });

  // 初期データの読み込み
  loadApplicationData();
}

function(container, apiUrl, tables) {
  let editingId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#classification-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.分類基準名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.文書種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${r.補助金関連度レベル === 3 ? '#ff6a00' : r.補助金関連度レベル === 2 ? '#ffa500' : '#888'}; color: #fff;">
            ${r.補助金関連度レベル === 3 ? '高' : r.補助金関連度レベル === 2 ? '中' : '低'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.処理ルート || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: center;">${r.優先度 || 1}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${r.有効フラグ ? 'var(--primary)' : '#666'}; color: #fff;">
            ${r.有効フラグ ? '有効' : '無効'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString() : ""} 〜 ${r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString() : ""}
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="margin-right: 4px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ描画
  window.aivicApi.list(9).then(rows => {
    if (rows) renderRows(rows);
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.trim();
    const rows = await window.aivicApi.list(9);
    if (rows) {
      const filtered = keyword ? rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      ) : rows;
      renderRows(filtered);
    }
  });

  // 4. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(9);
    if (!rows) return;

    const headers = ["分類基準名", "文書種別", "補助金関連度", "処理ルート", "優先度", "有効状態", "適用開始日", "適用終了日"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        `"${r.分類基準名 || ""}"`,
        `"${r.文書種別 || ""}"`,
        `"${r.補助金関連度レベル === 3 ? '高' : r.補助金関連度レベル === 2 ? '中' : '低'}"`,
        `"${r.処理ルート || ""}"`,
        r.優先度 || 1,
        r.有効フラグ ? "有効" : "無効",
        `"${r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString() : ""}"`,
        `"${r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString() : ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "classification_criteria.csv";
    link.click();
  });

  // 5. 新規作成モーダル
  container.querySelector("#btn-new").addEventListener("click", () => {
    editingId = null;
    container.querySelector("#modal-title").textContent = "新規分類基準作成";
    container.querySelector("#classification-form").reset();
    container.querySelector("#input-active").checked = true;

    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    container.querySelector("#input-start-date").value = today;

    container.querySelector("#modal-form").style.display = "block";
  });

  // 6. モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#modal-form").style.display = "none";
  });

  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#modal-form").style.display = "none";
  });

  // 7. フォーム保存
  container.querySelector("#classification-form").addEventListener("submit", async (e) => {
    e.preventDefault();

    const name = container.querySelector("#input-name").value.trim();
    const docType = container.querySelector("#select-document-type").value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;
    const keywords = container.querySelector("#input-keywords").value.trim();
    const route = container.querySelector("#select-route").value;
    const priority = parseInt(container.querySelector("#input-priority").value) || 1;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const active = container.querySelector("#input-active").checked;

    // バリデーション
    if (!name) {
      alert("分類基準名を入力してください");
      return;
    }
    if (!docType) {
      alert("文書種別を選択してください");
      return;
    }
    if (!subsidyLevel) {
      alert("補助金関連度を選択してください");
      return;
    }
    if (!keywords) {
      alert("キーワード条件を入力してください");
      return;
    }
    if (!route) {
      alert("処理ルートを選択してください");
      return;
    }
    if (!startDate) {
      alert("適用開始日を入力してください");
      return;
    }
    if (endDate && new Date(startDate) > new Date(endDate)) {
      alert("適用開始日は終了日より前の日付を設定してください");
      return;
    }

    // 重複チェック
    if (!editingId) {
      const existing = await window.aivicApi.list(9);
      if (existing && existing.some(r => r.分類基準名 === name)) {
        alert("同じ分類基準名が既に存在します");
        return;
      }
    }

    const data = {
      分類基準名: name,
      文書種別: docType,
      補助金関連度レベル: parseInt(subsidyLevel),
      キーワード条件: keywords,
      処理ルート: route,
      優先度: priority,
      適用開始日: startDate,
      適用終了日: endDate || null,
      有効フラグ: active,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    let result;
    if (editingId) {
      result = await window.aivicApi.update(9, editingId, data);
    } else {
      result = await window.aivicApi.save(9, data);
    }

    if (result) {
      alert("分類基準を保存しました");
      container.querySelector("#modal-form").style.display = "none";
      const rows = await window.aivicApi.list(9);
      if (rows) renderRows(rows);
    }
  });

  // 8. 条件プレビュー
  container.querySelector("#btn-preview").addEventListener("click", () => {
    const name = container.querySelector("#input-name").value.trim();
    const docType = container.querySelector("#select-document-type").value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;
    const keywords = container.querySelector("#input-keywords").value.trim();
    const route = container.querySelector("#select-route").value;
    const priority = container.querySelector("#input-priority").value;

    const previewContent = `
      <strong>分類基準名:</strong> ${name || "(未入力)"}<br>
      <strong>文書種別:</strong> ${docType || "(未選択)"}<br>
      <strong>補助金関連度:</strong> ${subsidyLevel ? (subsidyLevel === '3' ? '高' : subsidyLevel === '2' ? '中' : '低') : "(未選択)"}<br>
      <strong>キーワード条件:</strong> ${keywords || "(未入力)"}<br>
      <strong>処理ルート:</strong> ${route || "(未選択)"}<br>
      <strong>優先度:</strong> ${priority || "1"}<br><br>
      <strong>判定条件:</strong><br>
      申請書類が「${docType || "指定文書種別"}」で、内容に「${keywords || "指定キーワード"}」が含まれる場合、
      補助金関連度「${subsidyLevel ? (subsidyLevel === '3' ? '高' : subsidyLevel === '2' ? '中' : '低') : "指定レベル"}」として
      「${route || "指定処理ルート"}」で処理する（優先度: ${priority || "1"}）
    `;

    container.querySelector("#preview-content").innerHTML = previewContent;
    container.querySelector("#modal-preview").style.display = "block";
  });

  container.querySelector("#btn-close-preview").addEventListener("click", () => {
    container.querySelector("#modal-preview").style.display = "none";
  });

  // 9. 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この分類基準を削除しますか？")) return;

      const result = await window.aivicApi.delete(9, deleteBtn.dataset.id);
      if (result !== null) {
        const rows = await window.aivicApi.list(9);
        if (rows) renderRows(rows);
      }
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      editingId = editBtn.dataset.id;
      const rows = await window.aivicApi.list(9);
      const record = rows?.find(r => r.id === editingId);

      if (record) {
        container.querySelector("#modal-title").textContent = "分類基準編集";
        container.querySelector("#input-name").value = record.分類基準名 || "";
        container.querySelector("#select-document-type").value = record.文書種別 || "";

        const subsidyRadio = container.querySelector(`input[name="subsidy-level"][value="${record.補助金関連度レベル}"]`);
        if (subsidyRadio) subsidyRadio.checked = true;

        container.querySelector("#input-keywords").value = record.キーワード条件 || "";
        container.querySelector("#select-route").value = record.処理ルート || "";
        container.querySelector("#input-priority").value = record.優先度 || 1;
        container.querySelector("#input-start-date").value = record.適用開始日 ? record.適用開始日.split('T')[0] : "";
        container.querySelector("#input-end-date").value = record.適用終了日 ? record.適用終了日.split('T')[0] : "";
        container.querySelector("#input-active").checked = record.有効フラグ;

        container.querySelector("#modal-form").style.display = "block";
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentRouteId = null;
  let approvalSteps = [];

  // 承認ステップテーブル再描画
  function renderApprovalSteps() {
    const tbody = container.querySelector("#approval-steps-tbody");
    tbody.innerHTML = approvalSteps.map((step, index) => `
      <tr data-step-id="${step.id}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <div style="display: flex; align-items: center; gap: 4px;">
            ${step.order}
            <button class="move-up-btn" data-index="${index}" style="background: transparent; border: none; color: var(--text-muted); cursor: pointer; padding: 2px;" ${index === 0 ? 'disabled' : ''}>↑</button>
            <button class="move-down-btn" data-index="${index}" style="background: transparent; border: none; color: var(--text-muted); cursor: pointer; padding: 2px;" ${index === approvalSteps.length - 1 ? 'disabled' : ''}>↓</button>
          </div>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${step.approverName}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <input type="checkbox" ${step.required ? 'checked' : ''} onchange="updateStepRequired('${step.id}', this.checked)" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <input type="checkbox" ${step.proxyAllowed ? 'checked' : ''} onchange="updateStepProxy('${step.id}', this.checked)" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <button class="delete-step-btn action-btn secondary" data-step-id="${step.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.display = "block";
    setTimeout(() => {
      errorDiv.style.display = "none";
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const routeName = container.querySelector("#route-name").value.trim();
    const documentType = container.querySelector("#document-type").value;
    const delayHours = container.querySelector("#delay-hours").value;

    if (!routeName) {
      showError("処理ルート名は必須です");
      return false;
    }

    if (routeName.length > 100) {
      showError("処理ルート名は100文字以内で入力してください");
      return false;
    }

    if (!documentType) {
      showError("文書種別を選択してください");
      return false;
    }

    if (approvalSteps.length === 0) {
      showError("承認者を設定してください");
      return false;
    }

    const hasRequired = approvalSteps.some(step => step.required);
    if (!hasRequired && container.querySelector("#required-approval").checked) {
      showError("必須承認者が設定されていません");
      return false;
    }

    if (delayHours && parseFloat(delayHours) < 0) {
      showError("遅延検知設定には正の数値を入力してください");
      return false;
    }

    return true;
  }

  // 初期データ読み込み
  async function loadRouteData() {
    try {
      const routes = await window.aivicApi.list(7); // 処理ルートテーブル
      if (routes && routes.length > 0) {
        const route = routes[0];
        currentRouteId = route.id;

        container.querySelector("#route-id").value = route.id || "";
        container.querySelector("#route-name").value = route.申請書類ID || "";
        container.querySelector("#document-type").value = route.承認フロー定義ID || "";
        container.querySelector("#delay-hours").value = route.期限日時 ? "24" : "";
        container.querySelector("#required-approval").checked = route.優先度 > 2;
        container.querySelector("#proxy-approval").checked = route.自動処理フラグ;

        // サンプル承認ステップデータ
        approvalSteps = [
          { id: "step1", order: 1, approverName: "田中部長", required: true, proxyAllowed: false },
          { id: "step2", order: 2, approverName: "佐藤課長", required: false, proxyAllowed: true }
        ];

        renderApprovalSteps();
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 承認者追加モーダル制御
  container.querySelector("#add-approver-btn").addEventListener("click", () => {
    container.querySelector("#add-approver-modal").style.display = "flex";
    container.querySelector("#modal-order").value = approvalSteps.length + 1;
  });

  container.querySelector("#modal-cancel-btn").addEventListener("click", () => {
    container.querySelector("#add-approver-modal").style.display = "none";
    container.querySelector("#modal-approver").value = "";
    container.querySelector("#modal-order").value = "";
  });

  container.querySelector("#modal-add-btn").addEventListener("click", () => {
    const approver = container.querySelector("#modal-approver").value;
    const order = parseInt(container.querySelector("#modal-order").value);

    if (!approver) {
      showError("承認者を選択してください");
      return;
    }

    if (!order || order < 1) {
      showError("承認順序を正しく入力してください");
      return;
    }

    const approverNames = {
      "user1": "田中部長",
      "user2": "佐藤課長", 
      "user3": "鈴木主任",
      "user4": "山田係長"
    };

    const newStep = {
      id: `step_${Date.now()}`,
      order: order,
      approverName: approverNames[approver],
      required: false,
      proxyAllowed: false
    };

    approvalSteps.push(newStep);
    approvalSteps.sort((a, b) => a.order - b.order);
    renderApprovalSteps();

    container.querySelector("#add-approver-modal").style.display = "none";
    container.querySelector("#modal-approver").value = "";
    container.querySelector("#modal-order").value = "";
  });

  // ステップ並び替え
  container.addEventListener("click", (e) => {
    const moveUpBtn = e.target.closest(".move-up-btn");
    const moveDownBtn = e.target.closest(".move-down-btn");
    const deleteBtn = e.target.closest(".delete-step-btn");

    if (moveUpBtn) {
      const index = parseInt(moveUpBtn.dataset.index);
      if (index > 0) {
        [approvalSteps[index], approvalSteps[index - 1]] = [approvalSteps[index - 1], approvalSteps[index]];
        approvalSteps.forEach((step, i) => step.order = i + 1);
        renderApprovalSteps();
      }
    }

    if (moveDownBtn) {
      const index = parseInt(moveDownBtn.dataset.index);
      if (index < approvalSteps.length - 1) {
        [approvalSteps[index], approvalSteps[index + 1]] = [approvalSteps[index + 1], approvalSteps[index]];
        approvalSteps.forEach((step, i) => step.order = i + 1);
        renderApprovalSteps();
      }
    }

    if (deleteBtn) {
      const stepId = deleteBtn.dataset.stepId;
      if (confirm("この承認者を削除しますか？")) {
        approvalSteps = approvalSteps.filter(step => step.id !== stepId);
        approvalSteps.forEach((step, i) => step.order = i + 1);
        renderApprovalSteps();
      }
    }
  });

  // グローバル関数定義
  window.updateStepRequired = (stepId, required) => {
    const step = approvalSteps.find(s => s.id === stepId);
    if (step) step.required = required;
  };

  window.updateStepProxy = (stepId, proxyAllowed) => {
    const step = approvalSteps.find(s => s.id === stepId);
    if (step) step.proxyAllowed = proxyAllowed;
  };

  // 更新ボタン
  container.querySelector("#update-btn").addEventListener("click", async () => {
    if (!validateForm()) return;

    if (!confirm("処理ルートを更新しますか？")) return;

    try {
      const updateData = {
        申請書類ID: container.querySelector("#route-name").value.trim(),
        承認フロー定義ID: container.querySelector("#document-type").value,
        現在ステップ番号: 1,
        処理状況: "申請中",
        優先度: container.querySelector("#required-approval").checked ? 3 : 2,
        自動処理フラグ: container.querySelector("#proxy-approval").checked,
        備考: `遅延検知: ${container.querySelector("#delay-hours").value || "未設定"}時間`,
        更新日時: new Date().toISOString(),
        更新者ID: "current-user"
      };

      const result = await window.aivicApi.update(7, currentRouteId, updateData);

      if (result) {
        alert("処理ルートが正常に更新されました");
        window.showScreen("scr-1779422283293"); // 処理ルート変更・通知画面に戻る
      } else {
        showError("更新に失敗しました");
      }
    } catch (error) {
      console.error("更新エラー:", error);
      showError("更新中にエラーが発生しました");
    }
  });

  // キャンセルボタン
  container.querySelector("#cancel-btn").addEventListener("click", () => {
    if (confirm("編集内容を破棄して戻りますか？")) {
      window.showScreen("scr-1779422283293");
    }
  });

  // 初期化
  loadRouteData();
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let currentDetectionResult = null;

  // DOM要素の取得
  const fileUpload = container.querySelector('#file-upload');
  const btnUpload = container.querySelector('#btn-upload');
  const documentTypeSelect = container.querySelector('#document-type-select');
  const autoDetectionResult = container.querySelector('#auto-detection-result');
  const accuracyBar = container.querySelector('#accuracy-bar');
  const accuracyPercentage = container.querySelector('#accuracy-percentage');
  const subsidyScore = container.querySelector('#subsidy-score');
  const documentPreview = container.querySelector('#document-preview');
  const btnPreview = container.querySelector('#btn-preview');
  const btnAutoDetect = container.querySelector('#btn-auto-detect');
  const btnReDetect = container.querySelector('#btn-re-detect');
  const btnConfirmFlow = container.querySelector('#btn-confirm-flow');
  const btnFinalize = container.querySelector('#btn-finalize');
  const linkDocumentMaster = container.querySelector('#link-document-master');
  const errorMessage = container.querySelector('#error-message');
  const historyTbody = container.querySelector('#history-tbody');

  // 文書種別マスタの選択肢を動的に設定
  function loadDocumentTypes() {
    if (tables[2] && tables[2].records) {
      documentTypeSelect.innerHTML = '<option value="">選択してください</option>';
      tables[2].records.forEach(record => {
        if (record.有効フラグ) {
          const option = document.createElement('option');
          option.value = record.文書種別コード;
          option.textContent = record.文書種別名;
          documentTypeSelect.appendChild(option);
        }
      });
    }
  }

  // 判定履歴の再描画
  function renderHistory(records) {
    if (!records || records.length === 0) {
      historyTbody.innerHTML = '<tr><td colspan="5" style="padding: 10px; text-align: center; color: var(--text-muted); font-size: 12px;">判定履歴がありません</td></tr>';
      return;
    }

    historyTbody.innerHTML = records.map(record => `
      <tr>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.作成日時 ? new Date(record.作成日時).toLocaleString() : ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.文書名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.判定結果 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.判定精度 || ''}%</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.判定者名 || ''}</td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 判定精度の更新
  function updateAccuracy(percentage) {
    accuracyBar.style.width = percentage + '%';
    accuracyPercentage.textContent = percentage + '%';

    // 精度に応じて色を変更
    if (percentage >= 80) {
      accuracyBar.style.background = '#10b981'; // 緑
    } else if (percentage >= 50) {
      accuracyBar.style.background = '#f59e0b'; // 黄
    } else {
      accuracyBar.style.background = '#ef4444'; // 赤
    }
  }

  // ファイルアップロード処理
  btnUpload.addEventListener('click', async () => {
    const file = fileUpload.files[0];
    if (!file) {
      showError('ファイルを選択してください。');
      return;
    }

    // ファイル形式チェック
    const allowedTypes = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
    if (!allowedTypes.includes(file.type)) {
      showError('対応していないファイル形式です。PDF、Word、Excel形式のファイルをアップロードしてください。');
      return;
    }

    // ファイルサイズチェック（10MB）
    if (file.size > 10 * 1024 * 1024) {
      showError('ファイルサイズが上限（10MB）を超えています。');
      return;
    }

    currentFile = file;
    documentPreview.textContent = `ファイル「${file.name}」がアップロードされました。プレビューボタンをクリックして内容を確認してください。`;

    // 自動判定を実行
    await executeAutoDetection();
  });

  // 自動判定実行
  async function executeAutoDetection() {
    if (!currentFile) {
      showError('ファイルをアップロードしてください。');
      return;
    }

    try {
      // 模擬的な判定処理
      const mockDetection = {
        documentType: 'subsidy-application',
        documentTypeName: '補助金申請書',
        accuracy: Math.floor(Math.random() * 40) + 60, // 60-99%
        subsidyScore: Math.floor(Math.random() * 100)
      };

      currentDetectionResult = mockDetection;
      autoDetectionResult.textContent = mockDetection.documentTypeName;
      updateAccuracy(mockDetection.accuracy);
      subsidyScore.textContent = mockDetection.subsidyScore;
      documentTypeSelect.value = mockDetection.documentType;

      // 判定履歴に追加
      const historyRecord = {
        文書名: currentFile.name,
        判定結果: mockDetection.documentTypeName,
        判定精度: mockDetection.accuracy,
        判定者名: '自動判定',
        作成日時: new Date().toISOString()
      };

      if (window.aivicApi) {
        await window.aivicApi.save(4, historyRecord); // 承認履歴テーブルに保存
        const historyRecords = await window.aivicApi.list(4);
        renderHistory(historyRecords);
      }

    } catch (error) {
      showError('判定処理中にエラーが発生しました。');
    }
  }

  // 自動判定ボタン
  btnAutoDetect.addEventListener('click', executeAutoDetection);

  // 再判定ボタン
  btnReDetect.addEventListener('click', async () => {
    if (!currentFile) {
      showError('ファイルをアップロードしてください。');
      return;
    }
    await executeAutoDetection();
  });

  // プレビューボタン
  btnPreview.addEventListener('click', () => {
    if (!currentFile) {
      showError('ファイルをアップロードしてください。');
      return;
    }

    const reader = new FileReader();
    reader.onload = function(e) {
      const content = e.target.result;
      documentPreview.innerHTML = `
        <div style="font-weight: 600; margin-bottom: 8px;">ファイル名: ${currentFile.name}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px;">サイズ: ${(currentFile.size / 1024).toFixed(1)} KB</div>
        <div style="border-top: 1px solid rgba(255,255,255,0.1); padding-top: 8px;">
          ${content.substring(0, 500)}${content.length > 500 ? '...' : ''}
        </div>
      `;
    };
    reader.readAsText(currentFile);
  });

  // 承認フロー確認ボタン
  btnConfirmFlow.addEventListener('click', () => {
    if (!currentDetectionResult) {
      showError('文書種別を判定してください。');
      return;
    }
    window.showScreen("scr-1779422575885");
  });

  // 判定結果確定ボタン
  btnFinalize.addEventListener('click', async () => {
    const selectedType = documentTypeSelect.value;
    if (!selectedType) {
      showError('文書種別を選択してください。');
      return;
    }

    if (!currentFile) {
      showError('ファイルをアップロードしてください。');
      return;
    }

    try {
      // 申請書類として保存
      const applicationData = {
        申請タイトル: currentFile.name,
        申請種別: selectedType,
        申請内容: `文書種別判定により${autoDetectionResult.textContent}として分類`,
        承認状態: '申請中',
        承認段階: 1,
        緊急フラグ: false,
        添付ファイル有無: true,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      if (window.aivicApi) {
        await window.aivicApi.save(1, applicationData);
        alert('判定結果が確定されました。');

        // フォームリセット
        fileUpload.value = '';
        documentTypeSelect.value = '';
        autoDetectionResult.textContent = '未判定';
        updateAccuracy(0);
        subsidyScore.textContent = '0';
        documentPreview.textContent = 'ファイルをアップロードしてプレビューを表示してください';
        currentFile = null;
        currentDetectionResult = null;
      }
    } catch (error) {
      showError('確定処理中にエラーが発生しました。');
    }
  });

  // 文書種別マスタ参照リンク
  linkDocumentMaster.addEventListener('click', (e) => {
    e.preventDefault();
    // 文書種別マスタ画面への遷移（仮想的な画面ID）
    if (window.showScreen) {
      window.showScreen("document-master");
    }
  });

  // 初期化処理
  loadDocumentTypes();

  // 初期履歴データの読み込み
  if (window.aivicApi) {
    window.aivicApi.list(4).then(records => {
      renderHistory(records || []);
    }).catch(() => {
      renderHistory([]);
    });
  } else {
    renderHistory(tables[4]?.records || []);
  }
}

function(container, apiUrl, tables) {
  let currentApplicationId = null;
  let currentJudgment = null;

  // 初期データの設定
  function initializeData() {
    const applications = tables[0]?.records || [];
    const documentTypes = tables[2]?.records || [];
    const users = tables[1]?.records || [];

    if (applications.length > 0) {
      const firstApp = applications[0];
      currentApplicationId = firstApp.id;

      // 申請書類IDを設定
      container.querySelector("#application-id").value = firstApp.id || '';

      // 申請者情報を設定
      const applicant = users.find(u => u.id === firstApp.applicantId);
      if (applicant) {
        container.querySelector("#applicant-name").textContent = applicant.userName || '-';
        container.querySelector("#applicant-dept").textContent = applicant.department || '-';
      }

      if (firstApp.createdAt) {
        const date = new Date(firstApp.createdAt);
        container.querySelector("#application-date").textContent = date.toLocaleString('ja-JP');
      }

      // 書類内容プレビューを設定
      if (firstApp.applicationContent) {
        container.querySelector("#document-preview").innerHTML = `
          <div style="white-space: pre-wrap;">${firstApp.applicationContent}</div>
        `;
      }

      // 文書種別を設定
      if (firstApp.applicationType) {
        const typeSelect = container.querySelector("#document-type");
        typeSelect.value = getDocumentTypeCode(firstApp.applicationType);
      }
    }
  }

  // 文書種別名からコードを取得
  function getDocumentTypeCode(typeName) {
    const typeMap = {
      '契約書': 'contract',
      '申請書': 'application', 
      '報告書': 'report',
      '請求書': 'invoice',
      '領収書': 'receipt'
    };
    return typeMap[typeName] || 'application';
  }

  // 判定実行
  function executeJudgment() {
    const documentType = container.querySelector("#document-type").value;
    const applicationId = container.querySelector("#application-id").value;

    if (!documentType) {
      showError("文書種別を選択してください");
      return;
    }

    if (!applicationId) {
      showError("申請書類IDが設定されていません");
      return;
    }

    // 判定ロジック
    const judgment = performJudgment(documentType);
    currentJudgment = judgment;

    // 結果を表示
    displayJudgmentResult(judgment);
    hideError();
  }

  // 判定ロジック
  function performJudgment(documentType) {
    const subsidyRelatedTypes = ['application', 'report'];
    const digitalOnlyTypes = ['invoice', 'receipt'];

    let result, confidence, subsidyLevel, recommendedRoute, reason;

    if (subsidyRelatedTypes.includes(documentType)) {
      result = 'ハイブリッド処理推奨';
      confidence = '85%';
      subsidyLevel = '高';
      recommendedRoute = 'ハイブリッド処理';
      reason = '補助金関連書類のため、電子化と紙媒体の併用処理が適切です。法的要件と利便性を両立できます。';
    } else if (digitalOnlyTypes.includes(documentType)) {
      result = '電子化可能';
      confidence = '95%';
      subsidyLevel = '低';
      recommendedRoute = '電子処理';
      reason = '定型的な書類で電子化に適しています。デジタル署名により法的効力を確保できます。';
    } else {
      result = '要検討';
      confidence = '60%';
      subsidyLevel = '中';
      recommendedRoute = 'ハイブリッド処理';
      reason = '判定基準が曖昧なため、安全側の処理ルートとしてハイブリッド処理を推奨します。';
    }

    return { result, confidence, subsidyLevel, recommendedRoute, reason };
  }

  // 判定結果表示
  function displayJudgmentResult(judgment) {
    container.querySelector("#judgment-status").textContent = judgment.result;
    container.querySelector("#judgment-confidence").textContent = `信頼度: ${judgment.confidence}`;
    container.querySelector("#subsidy-level").textContent = judgment.subsidyLevel;
    container.querySelector("#recommended-route").textContent = judgment.recommendedRoute;
    container.querySelector("#judgment-reason").value = judgment.reason;

    // 結果に応じた色分け
    const statusEl = container.querySelector("#judgment-status");
    if (judgment.result.includes('可能')) {
      statusEl.style.color = '#10b981';
    } else if (judgment.result.includes('不可')) {
      statusEl.style.color = '#ef4444';
    } else {
      statusEl.style.color = '#f59e0b';
    }
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector("#error-message");
    errorEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    container.querySelector("#error-message").style.display = 'none';
  }

  // 手動オーバーライド切り替え
  function toggleManualOverride() {
    const checkbox = container.querySelector("#manual-override");
    const options = container.querySelector("#override-options");

    if (checkbox.checked) {
      options.style.display = 'block';
    } else {
      options.style.display = 'none';
      container.querySelector("#override-judgment").value = '';
      container.querySelector("#override-reason").value = '';
    }
  }

  // オーバーライド実行
  function executeOverride() {
    const overrideJudgment = container.querySelector("#override-judgment").value;
    const overrideReason = container.querySelector("#override-reason").value;

    if (!overrideJudgment) {
      showError("オーバーライド判定を選択してください");
      return;
    }

    if (!overrideReason.trim()) {
      showError("オーバーライド理由を入力してください");
      return;
    }

    // オーバーライド結果を反映
    const overrideResult = {
      result: overrideJudgment === 'digital' ? '電子化可能（手動）' : 
              overrideJudgment === 'paper' ? '電子化不可（手動）' : 'ハイブリッド処理（手動）',
      confidence: '手動設定',
      subsidyLevel: currentJudgment?.subsidyLevel || '中',
      recommendedRoute: overrideJudgment === 'digital' ? '電子処理' : 
                       overrideJudgment === 'paper' ? '紙処理' : 'ハイブリッド処理',
      reason: `【手動オーバーライド】${overrideReason}`
    };

    displayJudgmentResult(overrideResult);
    hideError();
  }

  // 承認フロー確認
  function checkApprovalFlow() {
    if (!currentApplicationId) {
      showError("申請書類が選択されていません");
      return;
    }

    // 承認フロー画面への遷移は実装されていないため、メッセージ表示
    alert("承認フロー確認画面への遷移機能は今後実装予定です");
  }

  // 処理ルート設定画面への遷移
  function goToRouteSettings() {
    window.showScreen("scr-1779422591281");
  }

  // イベントリスナー設定
  container.querySelector("#btn-execute-judgment").addEventListener("click", executeJudgment);
  container.querySelector("#btn-check-approval-flow").addEventListener("click", checkApprovalFlow);
  container.querySelector("#btn-route-setting").addEventListener("click", goToRouteSettings);
  container.querySelector("#manual-override").addEventListener("change", toggleManualOverride);

  // 文書種別変更時の処理
  container.querySelector("#document-type").addEventListener("change", function() {
    // 判定結果をリセット
    container.querySelector("#judgment-status").textContent = "未判定";
    container.querySelector("#judgment-confidence").textContent = "文書種別が変更されました";
    container.querySelector("#subsidy-level").textContent = "-";
    container.querySelector("#recommended-route").textContent = "-";
    container.querySelector("#judgment-reason").value = "";
    hideError();
  });

  // オーバーライド判定変更時の自動実行
  container.querySelector("#override-judgment").addEventListener("change", function() {
    const checkbox = container.querySelector("#manual-override");
    if (checkbox.checked && this.value) {
      executeOverride();
    }
  });

  // 初期化
  initializeData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#document-tbody");
  const resultCount = container.querySelector("#result-count");
  const errorMessage = container.querySelector("#error-message");

  // ユーザーマスタとルートマスタを参照用に保持
  const users = tables.find(t => t.tableName === 'ユーザー')?.records || [];
  const routes = tables.find(t => t.tableName === '処理ルート')?.records || [];
  const subsidyMaster = tables.find(t => t.tableName === '補助金関連度マスタ')?.records || [];

  // ユーザー名取得ヘルパー
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : '';
  }

  // 処理ルート名取得ヘルパー
  function getRouteName(routeId) {
    const route = routes.find(r => r.処理ルートID === routeId);
    return route ? route.処理状況 : '';
  }

  // 補助金関連度名取得ヘルパー
  function getSubsidyRelevanceName(level) {
    const subsidy = subsidyMaster.find(s => s.関連度レベル === level);
    return subsidy ? subsidy.補助金関連度名 : level === 1 ? '低' : level === 2 ? '中' : level === 3 ? '高' : '';
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 承認状態のバッジスタイル
  function getStatusBadge(status) {
    const colors = {
      '申請中': 'background: rgba(59, 130, 246, 0.1); color: #3b82f6; border: 1px solid rgba(59, 130, 246, 0.3);',
      '承認待ち': 'background: rgba(245, 158, 11, 0.1); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3);',
      '承認済': 'background: rgba(34, 197, 94, 0.1); color: #22c55e; border: 1px solid rgba(34, 197, 94, 0.3);',
      '差戻し': 'background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);',
      '却下': 'background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);',
      '取下げ': 'background: rgba(107, 114, 128, 0.1); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);'
    };
    const style = colors[status] || 'background: rgba(107, 114, 128, 0.1); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);';
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${style}">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; padding: 20px; color: var(--text-muted); font-size: 13px;">検索結果が見つかりませんでした</td></tr>';
      resultCount.textContent = '0件';
      return;
    }

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <a href="#" class="document-link" data-id="${row.申請書類ID}" style="color: var(--primary); text-decoration: none; cursor: pointer;">${row.申請書類ID?.slice(0,8) || ''}</a>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請種別 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請タイトル || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getUserName(row.申請者ID)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(row.作成日時)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getStatusBadge(row.承認状態)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getUserName(row.現在承認者ID)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getRouteName(row.処理ルートID) || '標準ルート'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getSubsidyRelevanceName(row.補助金関連度) || ''}</td>
      </tr>
    `).join('');

    resultCount.textContent = `${rows.length}件`;
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateSearchConditions() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    return true;
  }

  // 検索フィルター
  function filterRows(rows) {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const documentType = container.querySelector("#document-type").value;
    const approvalStatus = container.querySelector("#approval-status").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const applicantName = container.querySelector("#applicant-name").value.toLowerCase();
    const approverName = container.querySelector("#approver-name").value.toLowerCase();
    const processingRoute = container.querySelector("#processing-route").value;
    const subsidyRelevance = container.querySelector('input[name="subsidy-relevance"]:checked')?.value;

    return rows.filter(row => {
      // キーワード検索
      if (keyword) {
        const searchText = `${row.申請タイトル || ''} ${row.申請内容 || ''}`.toLowerCase();
        if (!searchText.includes(keyword)) return false;
      }

      // 文書種別
      if (documentType && row.申請種別 !== documentType) return false;

      // 承認状態
      if (approvalStatus && row.承認状態 !== approvalStatus) return false;

      // 申請日期間
      if (startDate || endDate) {
        const rowDate = new Date(row.作成日時);
        if (startDate && rowDate < new Date(startDate)) return false;
        if (endDate && rowDate > new Date(endDate + 'T23:59:59')) return false;
      }

      // 申請者名
      if (applicantName) {
        const applicantUserName = getUserName(row.申請者ID).toLowerCase();
        if (!applicantUserName.includes(applicantName)) return false;
      }

      // 承認者名
      if (approverName) {
        const approverUserName = getUserName(row.現在承認者ID).toLowerCase();
        if (!approverUserName.includes(approverName)) return false;
      }

      // 処理ルート
      if (processingRoute) {
        const routeName = getRouteName(row.処理ルートID) || '標準ルート';
        if (routeName !== processingRoute) return false;
      }

      // 補助金関連度
      if (subsidyRelevance) {
        const relevanceName = getSubsidyRelevanceName(row.補助金関連度);
        if (relevanceName !== subsidyRelevance) return false;
      }

      return true;
    });
  }

  // CSVエクスポート
  function exportToCSV(rows) {
    const headers = ['文書番号', '申請種別', '申請タイトル', '申請者', '申請日', '承認状態', '現在承認者', '処理ルート', '補助金関連度'];
    const csvData = [headers];

    rows.forEach(row => {
      csvData.push([
        row.申請書類ID?.slice(0,8) || '',
        row.申請種別 || '',
        row.申請タイトル || '',
        getUserName(row.申請者ID),
        formatDate(row.作成日時),
        row.承認状態 || '',
        getUserName(row.現在承認者ID),
        getRouteName(row.処理ルートID) || '標準ルート',
        getSubsidyRelevanceName(row.補助金関連度) || ''
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `電子文書検索結果_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      renderRows(rows);
    } else {
      renderRows(tables[1]?.records || []);
    }
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    if (!validateSearchConditions()) return;

    try {
      const rows = await window.aivicApi.list(1);
      if (rows) {
        const filteredRows = filterRows(rows);
        renderRows(filteredRows);
      } else {
        showError('データの取得に失敗しました');
      }
    } catch (error) {
      showError('検索中にエラーが発生しました');
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#search-keyword").value = '';
    container.querySelector("#document-type").value = '';
    container.querySelector("#approval-status").value = '';
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#applicant-name").value = '';
    container.querySelector("#approver-name").value = '';
    container.querySelector("#processing-route").value = '';
    container.querySelectorAll('input[name="subsidy-relevance"]').forEach(radio => radio.checked = false);

    // 全件表示
    window.aivicApi.list(1).then(rows => {
      if (rows) {
        renderRows(rows);
      } else {
        renderRows(tables[1]?.records || []);
      }
    });
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(1);
      if (rows) {
        const filteredRows = filterRows(rows);
        exportToCSV(filteredRows);
      } else {
        showError('データの取得に失敗しました');
      }
    } catch (error) {
      showError('エクスポート中にエラーが発生しました');
    }
  });

  // 文書番号リンククリック
  container.addEventListener("click", (e) => {
    const documentLink = e.target.closest(".document-link");
    if (documentLink) {
      e.preventDefault();
      const documentId = documentLink.dataset.id;
      // 申請書類確認画面へ遷移
      window.showScreen("scr-1779422434952");
    }
  });
}
